CREATE OR REPLACE FUNCTION public._waiter_req_simple_unit_price(p_seller uuid, p_item jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pid text := coalesce(
    nullif(trim(p_item ->> 'productId'), ''),
    nullif(trim(p_item ->> 'product_id'), '')
  );
  pr record;
  sel_size text := coalesce(
    nullif(trim(p_item ->> 'selectedSizeName'), ''),
    nullif(trim(p_item ->> 'selected_size_name'), '')
  );
  grams int := coalesce(
    (p_item ->> 'selectedWeightGrams')::int,
    (p_item ->> 'selected_weight_grams')::int,
    0
  );
  svc numeric := coalesce(
    (p_item ->> 'selectedServiceAmount')::numeric,
    (p_item ->> 'selected_service_amount')::numeric,
    null
  );
  sz_price numeric;
  w numeric;
begin
  if pid is null or pid = '' then
    return coalesce((p_item ->> 'price')::numeric, 0);
  end if;
  select * into pr from public._waiter_req_product_row(p_seller, pid);
  if not found then
    raise exception 'Ürün bulunamadı veya bu restorana ait değil: %', pid;
  end if;

  sz_price := public._waiter_req_size_unit_price(pr.size_options, sel_size);
  if sz_price is not null then
    return sz_price;
  end if;

  if coalesce(pr.pricing_mode, '') = 'weight_only'
     or (grams > 0 and coalesce(pr.price_per_kg, 0) > 0) then
    w := greatest(grams, 1);
    return (coalesce(pr.price_per_kg, 0) * (w::numeric / 1000.0));
  end if;

  if svc is not null and coalesce(pr.portion_price, 0) > 0 then
    return coalesce(pr.portion_price, pr.base_price, pr.price, 0) * svc;
  end if;

  return coalesce(pr.base_price, pr.price, 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_store_contract_for_rental(p_reservation_id uuid, p_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res public.vehicle_reservations%rowtype;
  v_ok boolean;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_res from public.vehicle_reservations where id = p_reservation_id for update;
  if not found or v_res.customer_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  select exists (
    select 1
    from public.store_contract_versions v
    join public.store_contracts c on c.id = v.contract_id
    where v.id = p_version_id
      and c.seller_id = v_res.seller_id
      and c.contract_type = 'vehicle_rental'
      and c.is_active
  ) into v_ok;
  if not v_ok then
    return jsonb_build_object('ok', false, 'error', 'contract_mismatch');
  end if;
  insert into public.store_contract_acceptances (
    reservation_id, contract_version_id, accepted_by
  ) values (p_reservation_id, p_version_id, v_uid)
  on conflict (reservation_id) do update
    set contract_version_id = excluded.contract_version_id,
        accepted_by = excluded.accepted_by,
        accepted_at = timezone('utc', now());
  update public.vehicle_reservations
  set terms_accepted_at = timezone('utc', now())
  where id = p_reservation_id;
  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_vehicle_rental_terms(p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  update public.vehicle_reservations
  set terms_accepted_at = timezone('utc', now())
  where id = p_reservation_id
    and customer_id = v_uid
    and status in ('pending_docs', 'pending_seller_review');
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_ihiz_business_account(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row public.ihiz_business_accounts%rowtype;
begin
  if v_uid is null then
    raise exception 'auth_required';
  end if;
  if not (
    public.ihiz_actor_owns_store(p_store_id, v_uid)
    or public.ihiz_actor_is_admin(v_uid)
  ) then
    raise exception 'forbidden';
  end if;

  update public.ihiz_business_accounts
  set
    status = 'active',
    activated_at = coalesce(activated_at, timezone('utc', now()))
  where store_id = p_store_id
  returning * into v_row;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  return jsonb_build_object('ok', true, 'status', v_row.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_can_write_finance()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid;
  effective_role text;
  denied_modules text[];
  allowed_modules text[];
begin
  uid := auth.uid();
  if uid is null then
    return false;
  end if;

  denied_modules := '{}'::text[];
  allowed_modules := null;

  if to_regclass('public.admin_user_permissions') is not null then
    select
      coalesce(a.denied_modules, '{}'::text[]),
      case
        when a.is_active is true
          and cardinality(coalesce(a.allowed_modules, '{}'::text[])) > 0
          then a.allowed_modules
        else null
      end
    into denied_modules, allowed_modules
    from public.admin_user_permissions a
    where a.user_id = uid and a.is_active = true
    limit 1;
  end if;

  if 'finance' = any(coalesce(denied_modules, '{}'::text[])) then
    return false;
  end if;

  effective_role := public.resolve_admin_effective_role(uid);
  if effective_role is null or not public.is_admin_role(effective_role) then
    return false;
  end if;

  if effective_role in ('super_admin', 'admin', 'admin_finance', 'admin_investor') then
    return true;
  end if;

  if allowed_modules is not null then
    return 'finance' = any(allowed_modules);
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_general_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_is_admin boolean := false;
  v_deleted_history integer := 0;
  v_deleted_items integer := 0;
  v_deleted_orders integer := 0;
  v_deleted_notifications integer := 0;
begin
  if v_actor is null then
    raise exception 'not authenticated';
  end if;

  select exists (
           select 1
           from public.users u
           where u.id = v_actor
             and (
               lower(coalesce(u.role, '')) in ('admin', 'super_admin')
               or lower(coalesce(u.role, '')) like 'admin_%'
             )
         )
         or exists (
           select 1
           from public.admin_user_permissions p
           where p.user_id = v_actor
             and coalesce(p.is_active, true) = true
         )
    into v_is_admin;

  if not v_is_admin then
    raise exception 'not authorized';
  end if;

  if to_regclass('public.order_item_status_history') is not null then
    delete from public.order_item_status_history
    where id is not null;
    get diagnostics v_deleted_history = row_count;
  end if;

  if to_regclass('public.order_items') is not null then
    delete from public.order_items
    where id is not null;
    get diagnostics v_deleted_items = row_count;
  end if;

  if to_regclass('public.orders') is not null then
    delete from public.orders
    where id is not null;
    get diagnostics v_deleted_orders = row_count;
  end if;

  if to_regclass('public.user_notifications') is not null then
    delete from public.user_notifications
    where id is not null;
    get diagnostics v_deleted_notifications = row_count;
  end if;

  return jsonb_build_object(
    'ok', true,
    'deleted_order_item_status_history', v_deleted_history,
    'deleted_order_items', v_deleted_items,
    'deleted_orders', v_deleted_orders,
    'deleted_notifications', v_deleted_notifications
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_insert_expense(p_title text, p_category text, p_amount numeric, p_expense_date date, p_type text, p_recurrence text, p_status text, p_payment_method text DEFAULT NULL::text, p_vendor text DEFAULT NULL::text, p_invoice_url text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS admin_expenses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result public.admin_expenses;
  v_uid uuid;
  v_created_by uuid;
begin
  if not public.admin_can_write_finance() then
    raise exception 'permission denied for admin expense insert' using errcode = '42501';
  end if;

  v_uid := auth.uid();
  v_created_by := null;
  if v_uid is not null and exists (select 1 from public.users u where u.id = v_uid) then
    v_created_by := v_uid;
  end if;

  insert into public.admin_expenses (
    title, category, amount, expense_date, type, recurrence, status,
    payment_method, vendor, invoice_url, note, created_by
  )
  values (
    trim(p_title),
    trim(p_category),
    p_amount,
    p_expense_date,
    p_type,
    p_recurrence,
    p_status,
    nullif(trim(coalesce(p_payment_method, '')), ''),
    nullif(trim(coalesce(p_vendor, '')), ''),
    nullif(trim(coalesce(p_invoice_url, '')), ''),
    nullif(trim(coalesce(p_note, '')), ''),
    v_created_by
  )
  returning * into result;

  return result;
end;
$function$

