CREATE OR REPLACE FUNCTION public.admin_issue_store_recovery_codes(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_actor uuid := auth.uid();
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  bytes bytea;
  code text;
  i int;
  n int;
  idx int;
  codes jsonb := jsonb_build_array();
begin
  if v_actor is null then
    raise exception 'not authenticated';
  end if;
  if not exists (
    select 1
    from public.users u
    where u.id = v_actor
      and (
        lower(coalesce(u.role, '')) in ('admin', 'super_admin')
        or lower(coalesce(u.role, '')) like 'admin_%'
      )
  ) then
    raise exception 'not authorized';
  end if;
  if p_store_id is null or not exists (
    select 1 from public.stores s where s.seller_id = p_store_id
  ) then
    raise exception 'store not found';
  end if;

  delete from public.store_recovery_codes
  where store_id = p_store_id
    and used_at is null;

  for n in 1..5 loop
    loop
      bytes := gen_random_bytes(8);
      code := '';
      for i in 0..7 loop
        idx := get_byte(bytes, i) % length(alphabet);
        code := code || substr(alphabet, idx + 1, 1);
        if i = 3 then
          code := code || '-';
        end if;
      end loop;
      exit when not exists (
        select 1
        from public.store_recovery_codes c
        where c.code_hash = public._store_recovery_hash(p_store_id, code)
      );
    end loop;

    insert into public.store_recovery_codes (
      store_id,
      code_hash,
      created_by
    ) values (
      p_store_id,
      public._store_recovery_hash(p_store_id, code),
      v_actor
    );
    codes := codes || jsonb_build_array(code);
  end loop;

  return jsonb_build_object('ok', true, 'store_id', p_store_id, 'codes', codes);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_vehicle_listings(p_status text DEFAULT NULL::text)
 RETURNS SETOF vehicle_listings
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.vehicle_is_admin() then
    raise exception 'forbidden';
  end if;
  if nullif(trim(coalesce(p_status, '')), '') is null then
    return query
      select * from public.vehicle_listings
      order by created_at desc;
    return;
  end if;
  return query
    select * from public.vehicle_listings
    where status = trim(p_status)
    order by created_at desc;
end;
$function$

CREATE OR REPLACE FUNCTION public.advance_ihiz_delivery_task(p_task_id uuid, p_next_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_task public.ihiz_delivery_tasks%rowtype;
  v_now timestamptz := timezone('utc', now());
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  if p_next_status not in (
    'preparing', 'ready_for_pickup', 'courier_assigned',
    'courier_picked_up', 'in_transit', 'delivered', 'cancelled'
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_status');
  end if;

  select * into v_task from public.ihiz_delivery_tasks where id = p_task_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if not public.ihiz_delivery_task_can_access(v_task, v_uid) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  update public.ihiz_delivery_tasks
  set
    status = p_next_status,
    picked_up_at = case when p_next_status = 'courier_picked_up' then coalesce(picked_up_at, v_now) else picked_up_at end,
    delivered_at = case when p_next_status = 'delivered' then coalesce(delivered_at, v_now) else delivered_at end,
    cancelled_at = case when p_next_status = 'cancelled' then coalesce(cancelled_at, v_now) else cancelled_at end,
    courier_lat = case when p_next_status in ('delivered', 'cancelled') then null else courier_lat end,
    courier_lng = case when p_next_status in ('delivered', 'cancelled') then null else courier_lng end,
    courier_location_updated_at = case when p_next_status in ('delivered', 'cancelled') then null else courier_location_updated_at end,
    updated_at = v_now
  where id = p_task_id
  returning * into v_task;

  perform public.ihiz_append_delivery_event(
    v_task.id,
    p_next_status,
    p_next_status,
    case p_next_status
      when 'courier_picked_up' then 'Kurye paketi teslim aldı'
      when 'in_transit' then 'Teslimat başladı'
      when 'delivered' then 'Teslim edildi'
      when 'cancelled' then 'Teslimat iptal edildi'
      when 'ready_for_pickup' then 'Paket kurye için hazır'
      when 'preparing' then 'Paket hazırlanıyor'
      else 'Durum güncellendi'
    end,
    null,
    'courier',
    v_uid,
    '{}'::jsonb
  );

  return jsonb_build_object('ok', true, 'status', v_task.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_waiter_order_request(p_request_id uuid, p_edited_items jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req public.waiter_order_requests%rowtype;
  v_src jsonb;
  v_recalc jsonb;
  v_print jsonb;
  v_table_order_id uuid;
  v_label text;
  v_area text;
  v_area_no int;
  v_print_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Yetkisiz istek.' using errcode = '42501';
  end if;

  select * into v_req
  from public.waiter_order_requests
  where id = p_request_id
  for update;

  if v_req.id is null then
    raise exception 'İstek bulunamadı.' using errcode = '22023';
  end if;

  if v_req.status <> 'pending_waiter_approval' then
    raise exception 'Bu istek onay için uygun değil.' using errcode = '22023';
  end if;

  if not public.user_can_access_restaurant(v_req.seller_id) then
    raise exception 'Bu işletme için yetkiniz yok.' using errcode = '42501';
  end if;

  v_src := coalesce(
    case
      when p_edited_items is null then null
      when jsonb_typeof(p_edited_items) = 'array'
        and jsonb_array_length(p_edited_items) > 0 then p_edited_items
      else null
    end,
    v_req.items_draft
  );

  if v_src is null
     or jsonb_typeof(v_src) <> 'array'
     or jsonb_array_length(v_src) = 0 then
    raise exception 'Onaylanacak kalem bulunamadı.' using errcode = '22023';
  end if;

  v_recalc := public.recalculate_waiter_request_items(v_req.seller_id, v_src);
  v_print := public.flatten_waiter_items_for_kitchen_print(
    v_req.seller_id,
    v_recalc
  );

  v_label := nullif(
    trim(coalesce(v_req.table_payload ->> 'display_table_label', '')),
    ''
  );
  v_area := nullif(trim(coalesce(v_req.table_payload ->> 'table_area_name', '')), '');
  begin
    v_area_no := (nullif(
      trim(coalesce(v_req.table_payload ->> 'area_table_number', '')),
      ''
    ))::integer;
  exception
    when others then
      v_area_no := null;
  end;
  if v_area_no is not null and v_area_no <= 0 then
    v_area_no := null;
  end if;

  insert into public.table_orders (
    seller_id,
    table_number,
    items,
    status,
    created_at,
    display_table_label,
    table_display_name,
    table_name,
    table_area_name,
    area_name,
    area_table_number,
    placement_source
  )
  values (
    v_req.seller_id,
    v_req.table_number,
    v_recalc,
    'new',
    now(),
    v_label,
    v_label,
    v_label,
    nullif(v_area, ''),
    nullif(v_area, ''),
    v_area_no,
    'customer'
  )
  returning id into v_table_order_id;

  update public.waiter_order_requests
  set
    status = 'approved_converted',
    resolved_by = auth.uid(),
    resolved_at = now(),
    resulting_table_order_id = v_table_order_id,
    server_items_snapshot = v_recalc,
    items_draft = v_src
  where id = p_request_id;

  v_print_result := null;
  if v_print is not null
     and jsonb_typeof(v_print) = 'array'
     and jsonb_array_length(v_print) > 0 then
    v_print_result := public.create_table_order_with_print_jobs(
      v_req.seller_id,
      v_req.table_number,
      v_print,
      auth.uid(),
      coalesce(
        (select u.email from auth.users u where u.id = auth.uid() limit 1),
        'Garson'
      ),
      format(
        'waiter_request:%s %s',
        p_request_id::text,
        coalesce(nullif(trim(v_req.customer_notes), ''), '')
      ),
      'new_order',
      'table'
    );
    update public.table_orders
    set status = 'sent'
    where id = v_table_order_id;
  end if;

  return jsonb_build_object(
    'request_id', p_request_id,
    'table_order_id', v_table_order_id,
    'items', v_recalc,
    'print_result', v_print_result
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_vehicle_rental_reservation(p_reservation_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res public.vehicle_reservations%rowtype;
  v_pct numeric;
  v_amount numeric := 0;
  v_next text := 'cancelled';
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_res from public.vehicle_reservations where id = p_reservation_id for update;
  if not found or v_res.customer_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_res.status not in (
    'pending_docs', 'pending_seller_review', 'pending_payment', 'confirmed', 'reserved'
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_state');
  end if;

  v_pct := public.vehicle_rental_refund_percent(
    v_res.cancellation_policy, v_res.pickup_at, 'customer'
  );
  if v_res.payment_status in ('paid', 'authorized') and v_pct > 0 then
    v_amount := round(v_res.total * v_pct / 100.0, 2);
    v_next := 'refund_pending';
    insert into public.vehicle_rental_refunds (booking_id, amount, reason, status)
    values (p_reservation_id, v_amount, coalesce(p_reason, 'customer_cancel'), 'refund_pending');
    update public.vehicle_reservations
    set status = v_next,
        payment_status = 'refund_pending',
        cancel_reason = p_reason,
        cancel_actor = 'customer',
        cancelled_at = timezone('utc', now()),
        refund_amount = v_amount,
        refund_reason = coalesce(p_reason, 'customer_cancel')
    where id = p_reservation_id;
    perform public.vehicle_rental_notify(
      v_res.customer_id, 'İade başlatıldı', 'İptal politikanıza göre iade kaydı açıldı.',
      'vehicle_rental_refund_started'
    );
  else
    update public.vehicle_reservations
    set status = 'cancelled',
        cancel_reason = p_reason,
        cancel_actor = 'customer',
        cancelled_at = timezone('utc', now()),
        refund_amount = 0
    where id = p_reservation_id;
  end if;

  if v_res.status in ('reserved', 'confirmed') then
    update public.vehicle_listings
    set status = 'active'
    where id = v_res.listing_id and status = 'reserved';
  end if;

  perform public.vehicle_rental_log_event(p_reservation_id, v_uid, 'customer_cancel', v_res.status, v_next);
  perform public.vehicle_rental_notify(
    v_res.seller_id, 'Müşteri iptali', 'Bir kiralama talebi müşteri tarafından iptal edildi.',
    'vehicle_rental_customer_cancelled'
  );
  return jsonb_build_object(
    'ok', true,
    'status', v_next,
    'refund_percent', v_pct,
    'refund_amount', v_amount
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_vehicle_handover(p_reservation_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res public.vehicle_reservations%rowtype;
  v_hash text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_res from public.vehicle_reservations where id = p_reservation_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if v_res.seller_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_res.status <> 'reserved' then
    return jsonb_build_object('ok', false, 'error', 'invalid_state');
  end if;
  if v_res.payment_status <> 'paid' then
    return jsonb_build_object('ok', false, 'error', 'payment_required');
  end if;
  v_hash := encode(digest(trim(coalesce(p_code, '')), 'sha256'), 'hex');
  if v_res.handover_code_hash is null or v_hash <> v_res.handover_code_hash then
    return jsonb_build_object('ok', false, 'error', 'invalid_code');
  end if;

  update public.vehicle_reservations
  set status = 'active_rental'
  where id = p_reservation_id;

  update public.vehicle_listings
  set status = 'rented'
  where id = v_res.listing_id;

  return jsonb_build_object('ok', true, 'status', 'active_rental');
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_vehicle_return(p_reservation_id uuid, p_odometer_km integer DEFAULT NULL::integer, p_fuel_level text DEFAULT NULL::text, p_damage_note text DEFAULT NULL::text, p_photo_urls text[] DEFAULT '{}'::text[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
