CREATE OR REPLACE FUNCTION public.create_order_from_cart(p_idempotency_key text, p_items jsonb, p_delivery_address jsonb DEFAULT '{}'::jsonb, p_delivery_type text DEFAULT 'standard'::text, p_delivery_slot text DEFAULT NULL::text, p_payment_method text DEFAULT 'card'::text, p_payment_card_name text DEFAULT NULL::text, p_payment_card_last4 text DEFAULT NULL::text, p_shipping_amount numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_order_id uuid;
  v_order_number text;
  v_subtotal numeric(12,2) := 0;
  v_item jsonb;
  v_product_id text;
  v_qty int;
  v_unit_price numeric(12,2);
  v_seller_id uuid;
  v_product_name text;
  v_store_name text;
  v_stock int;
  v_existing_order_id uuid;
begin
  if v_user_id is null then
    raise exception 'Giriş yapmanız gerekiyor.';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Sipariş verilecek ürün bulunamadı.';
  end if;

  if nullif(trim(coalesce(p_idempotency_key, '')), '') is not null then
    select o.id
    into v_existing_order_id
    from public.orders o
    where o.user_id = v_user_id
      and o.idempotency_key = trim(p_idempotency_key)
    limit 1;

    if v_existing_order_id is not null then
      return jsonb_build_object(
        'order_id', v_existing_order_id,
        'idempotent_replay', true
      );
    end if;
  end if;

  v_order_number := 'IBUL-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS');

  -- Ön doğrulama + subtotal
  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_product_id := trim(coalesce(v_item->>'product_id', ''));
    v_qty := greatest(1, coalesce((v_item->>'quantity')::int, 1));

    if v_product_id = '' then
      raise exception 'Sepetinizdeki bazı ürünler artık satışta değil.';
    end if;

    if not public.is_customer_checkout_eligible_product(v_product_id) then
      raise exception 'Bu ürün şu anda satışta değil.';
    end if;

    select
      p.seller_id,
      p.name,
      coalesce(s.business_name, p.store_name),
      coalesce(nullif(p.discount_price, 0), p.price, 0),
      coalesce(p.stock, 0)
    into v_seller_id, v_product_name, v_store_name, v_unit_price, v_stock
    from public.products p
    left join public.stores s on s.seller_id = p.seller_id
    where p.id::text = v_product_id
    for update;

    if not found then
      raise exception 'Sepetinizdeki bazı ürünler artık satışta değil.';
    end if;

    if v_stock < v_qty then
      raise exception 'Bu ürün şu anda stokta yok.';
    end if;

    v_subtotal := v_subtotal + (v_unit_price * v_qty);
  end loop;

  insert into public.orders (
    user_id,
    order_number,
    status,
    payment_method,
    payment_card_name,
    payment_card_last4,
    delivery_type,
    delivery_slot,
    delivery_address,
    subtotal_amount,
    shipping_amount,
    discount_amount,
    total_amount,
    idempotency_key
  ) values (
    v_user_id,
    v_order_number,
    'confirmed',
    coalesce(nullif(trim(p_payment_method), ''), 'card'),
    p_payment_card_name,
    p_payment_card_last4,
    p_delivery_type,
    p_delivery_slot,
    coalesce(p_delivery_address, '{}'::jsonb),
    v_subtotal,
    coalesce(p_shipping_amount, 0),
    0,
    v_subtotal + coalesce(p_shipping_amount, 0),
    nullif(trim(coalesce(p_idempotency_key, '')), '')
  )
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_product_id := trim(coalesce(v_item->>'product_id', ''));
    v_qty := greatest(1, coalesce((v_item->>'quantity')::int, 1));

    select
      p.seller_id,
      p.name,
      coalesce(s.business_name, p.store_name),
      coalesce(nullif(p.discount_price, 0), p.price, 0),
      coalesce(p.stock, 0)
    into v_seller_id, v_product_name, v_store_name, v_unit_price, v_stock
    from public.products p
    left join public.stores s on s.seller_id = p.seller_id
    where p.id::text = v_product_id
    for update;

    if v_stock < v_qty then
      raise exception 'Bu ürün şu anda stokta yok.';
    end if;

    update public.products
    set stock = greatest(0, coalesce(stock, 0) - v_qty),
        updated_at = now()
    where id::text = v_product_id
      and coalesce(stock, 0) >= v_qty;

    if not found then
      raise exception 'Bu ürün şu anda stokta yok.';
    end if;

    insert into public.order_items (
      order_id,
      seller_id,
      product_id,
      product_name,
      store_name,
      quantity,
      unit_price,
      total_price,
      status
    ) values (
      v_order_id,
      v_seller_id,
      v_product_id,
      v_product_name,
      v_store_name,
      v_qty,
      v_unit_price,
      v_unit_price * v_qty,
      'new'
    );
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'subtotal_amount', v_subtotal,
    'total_amount', v_subtotal + coalesce(p_shipping_amount, 0),
    'idempotent_replay', false
  );
exception
  when others then
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_table_order_with_print_jobs(p_restaurant_id uuid, p_table_number integer, p_items jsonb, p_waiter_id uuid DEFAULT NULL::uuid, p_waiter_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_job_type text DEFAULT 'new_order'::text, p_order_type text DEFAULT 'table'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id uuid;
  v_order_number text;
  v_table_id uuid;
  v_restaurant_name text;
  v_table_name text;
  v_waiter_name text;
  v_waiter_ref uuid;

  v_item jsonb;
  v_item_qty integer;
  v_item_unit_price numeric(12,2);
  v_item_line_total numeric(12,2);
  v_item_note text;
  v_item_name text;
  v_item_product_id text;
  v_item_station_id uuid;
  v_item_routing_enabled boolean;
  v_item_inserted_id uuid;

  v_product record;

  v_group record;
  v_printer_id uuid;
  v_printer_name text;
  v_printer_code text;
  v_printer_connection_type text;
  v_printer_ip_address text;
  v_printer_port integer;
  v_printer_device_identifier text;
  v_printer_paper_width_mm integer;
  v_items_payload jsonb;
  v_job_payload jsonb;
  v_print_job_id uuid;

  v_subtotal numeric(12,2) := 0;
  v_print_job_count integer := 0;
  v_print_job_ids jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Yetkisiz istek.' using errcode = '42501';
  end if;

  if auth.uid() <> p_restaurant_id then
    -- Allow active waiter/sub-admin accounts for this restaurant.
    if not exists (
      select 1
      from public.store_sub_admins sa
      join public.users u
        on lower(trim(u.email)) = lower(trim(sa.email))
      where sa.store_id = p_restaurant_id
        and u.id         = auth.uid()
        and sa.status    = 'active'
    ) then
      raise exception 'Bu restoran için işlem yetkiniz yok.' using errcode = '42501';
    end if;
  end if;

  if p_items is null
    or jsonb_typeof(p_items) <> 'array'
    or jsonb_array_length(p_items) = 0 then
    raise exception 'Sipariş kalemleri boş olamaz.' using errcode = '22023';
  end if;

  if p_job_type not in ('new_order', 'add_item', 'cancel_item', 'reprint') then
    raise exception 'Geçersiz job_type: %', p_job_type using errcode = '22023';
  end if;

  select business_name
  into v_restaurant_name
  from public.stores
  where seller_id = p_restaurant_id
  limit 1;

  if v_restaurant_name is null then
    raise exception 'Restoran bulunamadı.' using errcode = '22023';
  end if;

  select id
  into v_table_id
  from public.store_tables
  where seller_id = p_restaurant_id
    and table_number = p_table_number
    and is_active = true
  order by created_at desc
  limit 1;

  v_table_name := format('Masa %s', p_table_number);
  v_waiter_name := coalesce(nullif(trim(coalesce(p_waiter_name, '')), ''), 'Garson');
  v_waiter_ref := null;
  select u.id into v_waiter_ref
  from public.users u
  where u.id = coalesce(p_waiter_id, auth.uid())
  limit 1;

  v_order_number := format(
    'TBL-%s-%s',
    to_char(now(), 'YYYYMMDDHH24MISS'),
    upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6))
  );

  insert into public.orders (
    user_id,
    order_number,
    status,
    payment_method,
    delivery_type,
    subtotal_amount,
    shipping_amount,
    discount_amount,
    total_amount,
    currency,
    restaurant_id,
    table_id,
    waiter_id,
    order_status,
    order_type,
    notes
  )
  values (
    auth.uid(),
    v_order_number,
    'confirmed',
    'cash',
    'table',
    0,
    0,
    0,
    0,
    'TRY',
    p_restaurant_id,
    v_table_id,
    v_waiter_ref,
    'sent',
    coalesce(nullif(trim(coalesce(p_order_type, '')), ''), 'table'),
    nullif(trim(coalesce(p_notes, '')), '')
  )
  returning id into v_order_id;

  for v_item in
    select value from jsonb_array_elements(p_items)
  loop
    v_item_product_id := nullif(trim(coalesce(v_item.value ->> 'product_id', '')), '');
    v_item_name := coalesce(nullif(trim(coalesce(v_item.value ->> 'name', '')), ''), 'Ürün');
    v_item_note := nullif(trim(coalesce(v_item.value ->> 'notes', '')), '');

    v_item_qty := greatest(
      coalesce(nullif(regexp_replace(coalesce(v_item.value ->> 'quantity', '1'), '[^0-9]', '', 'g'), '')::integer, 1),
      1
    );

    if (v_item.value ? 'price') and jsonb_typeof(v_item.value -> 'price') = 'number' then
      v_item_unit_price := coalesce((v_item.value ->> 'price')::numeric, 0);
    else
      v_item_unit_price := public.parse_price_numeric(v_item.value ->> 'price');
    end if;

    select
      p.id::text as product_id_text,
      p.name,
      p.station_id,
      coalesce(p.printer_routing_enabled, true) as routing_enabled,
      coalesce(p.discount_price, p.price, 0)::numeric as fallback_price
    into v_product
    from public.products p
    where p.seller_id = p_restaurant_id
      and (
        (v_item_product_id is not null and p.id::text = v_item_product_id)
        or (v_item_product_id is null and lower(p.name) = lower(v_item_name))
      )
    limit 1;

    if found then
      v_item_product_id := coalesce(v_item_product_id, v_product.product_id_text);
      v_item_name := coalesce(nullif(v_item_name, 'Ürün'), v_product.name, v_item_name);
      v_item_station_id := coalesce(
        public.try_uuid(v_item.value ->> 'station_id'),
        v_product.station_id
      );
      v_item_routing_enabled := v_product.routing_enabled;
      if v_item_unit_price <= 0 then
        v_item_unit_price := coalesce(v_product.fallback_price, 0);
      end if;
    else
      v_item_station_id := public.try_uuid(v_item.value ->> 'station_id');
      v_item_routing_enabled := true;
    end if;

    v_item_line_total := round((v_item_qty::numeric * coalesce(v_item_unit_price, 0))::numeric, 2);
    v_subtotal := v_subtotal + v_item_line_total;

    insert into public.order_items (
      order_id,
      seller_id,
      product_id,
      product_name,
      quantity,
      unit_price,
      total_price,
      line_total,
      status,
      station_id,
      item_note,
      kitchen_status,
      sent_to_kitchen_at
    )
    values (
      v_order_id,
      p_restaurant_id,
      v_item_product_id,
      v_item_name,
      v_item_qty,
      coalesce(v_item_unit_price, 0),
      v_item_line_total,
      v_item_line_total,
      'new',
      v_item_station_id,
      v_item_note,
      case when v_item_routing_enabled then 'pending' else 'skipped' end,
      null
    )
    returning id into v_item_inserted_id;
  end loop;

  update public.orders
  set subtotal_amount = v_subtotal,
      total_amount = v_subtotal,
      order_status = 'sent'
  where id = v_order_id;

  for v_group in
    select
      oi.station_id,
      coalesce(s.name, 'Genel') as station_name,
      coalesce(s.code, 'GENEL') as station_code
    from public.order_items oi
    left join public.products p
      on p.id::text = oi.product_id
      and p.seller_id = p_restaurant_id
    left join public.stations s
      on s.id = oi.station_id
    where oi.order_id = v_order_id
      and coalesce(p.printer_routing_enabled, true)
    group by oi.station_id, s.name, s.code
  loop
    if v_group.station_id is not null then
      select
        sp.printer_id,
        pr.name as printer_name,
        pr.code as printer_code,
        pr.connection_type,
        pr.ip_address,
        pr.port,
        pr.device_identifier,
        pr.paper_width_mm
      into
        v_printer_id,
        v_printer_name,
        v_printer_code,
        v_printer_connection_type,
        v_printer_ip_address,
        v_printer_port,
        v_printer_device_identifier,
        v_printer_paper_width_mm
      from public.station_printers sp
      join public.printers pr
        on pr.id = sp.printer_id
       and pr.is_active = true
      where sp.station_id = v_group.station_id
      order by sp.is_primary desc, sp.created_at asc
      limit 1;
    else
      v_printer_id := null;
      v_printer_name := null;
      v_printer_code := null;
      v_printer_connection_type := null;
      v_printer_ip_address := null;
      v_printer_port := null;
      v_printer_device_identifier := null;
      v_printer_paper_width_mm := null;
      -- Skip the null-station "Genel" print job when the order has at least
      -- one item assigned to a named station.  Every routed item already goes
      -- to its own station ticket; a duplicate Genel ticket would only add
      -- noise.  When NO items have a station (station-free restaurants) the
      -- check evaluates to false and the single Genel ticket is kept.
      if exists (
        select 1
        from public.order_items oi2
        where oi2.order_id = v_order_id
          and oi2.station_id is not null
      ) then
        continue;
      end if;
    end if;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'order_item_id', oi.id,
          'product_name', oi.product_name,
          'quantity', oi.quantity,
          'item_note', oi.item_note,
          'unit_price', oi.unit_price,
          -- Persist structured display data from the incoming p_items payload
          -- so that reprints (which have no sourceItems) can still render
          -- plates, service_children and gramaj correctly.
          'amount_label', coalesce((
            select elem ->> 'amount_label'
            from jsonb_array_elements(p_items) elem
            where (elem ->> 'product_id') = oi.product_id::text
               or lower(elem ->> 'name') = lower(oi.product_name)
            limit 1
          ), ''),
          'plates', coalesce((
            select elem -> 'plates'
            from jsonb_array_elements(p_items) elem
            where (elem ->> 'product_id') = oi.product_id::text
               or lower(elem ->> 'name') = lower(oi.product_name)
            limit 1
          ), '[]'::jsonb),
          'service_children', coalesce((
            select elem -> 'service_children'
            from jsonb_array_elements(p_items) elem
            where (elem ->> 'product_id') = oi.product_id::text
               or lower(elem ->> 'name') = lower(oi.product_name)
            limit 1
          ), '[]'::jsonb)
        )
        order by oi.created_at asc
      ),
      '[]'::jsonb
    )
    into v_items_payload
    from public.order_items oi
    left join public.products p
      on p.id::text = oi.product_id
      and p.seller_id = p_restaurant_id
    where oi.order_id = v_order_id
      and oi.station_id is not distinct from v_group.station_id
      and coalesce(p.printer_routing_enabled, true);

    if jsonb_array_length(v_items_payload) = 0 then
      continue;
    end if;

    v_job_payload := jsonb_build_object(
      'restaurant_id', p_restaurant_id,
      'restaurant_name', v_restaurant_name,
      'order_id', v_order_id,
      'order_no', v_order_number,
      'table_name', v_table_name,
      'waiter_name', v_waiter_name,
      'station_id', v_group.station_id,
      'station_name', v_group.station_name,
      'station_code', v_group.station_code,
      'printer_id', v_printer_id,
      'printer_name', v_printer_name,
      'printer_code', v_printer_code,
      'printer_connection_type', v_printer_connection_type,
      'printer_ip_address', v_printer_ip_address,
      'printer_port', v_printer_port,
      'printer_device_identifier', v_printer_device_identifier,
      'paper_width_mm', v_printer_paper_width_mm,
      'job_type', p_job_type,
      'created_at', now(),
      'items', v_items_payload
    );

    insert into public.print_jobs (
      restaurant_id,
      order_id,
      station_id,
      printer_id,
      job_type,
      status,
      payload
    )
    values (
      p_restaurant_id,
      v_order_id,
      v_group.station_id,
      v_printer_id,
      p_job_type,
      'pending',
      v_job_payload
    )
    returning id into v_print_job_id;

    insert into public.print_job_items (print_job_id, order_item_id)
    select v_print_job_id, oi.id
    from public.order_items oi
    left join public.products p
      on p.id::text = oi.product_id
      and p.seller_id = p_restaurant_id
    where oi.order_id = v_order_id
      and oi.station_id is not distinct from v_group.station_id
      and coalesce(p.printer_routing_enabled, true);

    update public.order_items
    set sent_to_kitchen_at = coalesce(sent_to_kitchen_at, now()),
        kitchen_status = 'queued'
    where id in (
      select pji.order_item_id
      from public.print_job_items pji
      where pji.print_job_id = v_print_job_id
    );

    v_print_job_count := v_print_job_count + 1;
    v_print_job_ids := v_print_job_ids || to_jsonb(v_print_job_id);
  end loop;

  return jsonb_build_object(
    'status', 'ok',
    'restaurant_id', p_restaurant_id,
    'order_id', v_order_id,
    'order_number', v_order_number,
    'table_number', p_table_number,
    'print_job_count', v_print_job_count,
    'print_job_ids', v_print_job_ids
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_vehicle_rental_reservation(p_listing_id uuid, p_pickup_at timestamp with time zone, p_return_at timestamp with time zone, p_delivery_mode text, p_delivery_address text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_airport boolean DEFAULT false, p_dropoff_mode text DEFAULT NULL::text, p_dropoff_address text DEFAULT NULL::text, p_dropoff_lat double precision DEFAULT NULL::double precision, p_dropoff_lng double precision DEFAULT NULL::double precision, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text, p_customer_birth_date date DEFAULT NULL::date, p_customer_email text DEFAULT NULL::text, p_customer_note text DEFAULT NULL::text, p_customer_national_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_listing public.vehicle_listings%rowtype;
  v_settings public.vehicle_rental_settings%rowtype;
  v_days int;
  v_subtotal numeric;
  v_quote jsonb;
  v_fee numeric := 0;
  v_total numeric;
  v_id uuid;
  v_national text := nullif(regexp_replace(coalesce(p_customer_national_id, ''), '\D', '', 'g'), '');
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  if v_national is not null and not public.tr_national_id_valid(v_national) then
    return jsonb_build_object('ok', false, 'error', 'invalid_national_id');
  end if;
  if p_return_at <= p_pickup_at then
    return jsonb_build_object('ok', false, 'error', 'invalid_window');
  end if;
  if p_pickup_at < timezone('utc', now()) - interval '5 minutes' then
    return jsonb_build_object('ok', false, 'error', 'past_date');
  end if;
  if p_delivery_mode not in ('gallery_pickup', 'map_point', 'home_delivery') then
    return jsonb_build_object('ok', false, 'error', 'invalid_delivery_mode');
  end if;
  if p_dropoff_mode is not null
     and p_dropoff_mode not in ('gallery_pickup', 'map_point', 'home_delivery') then
    return jsonb_build_object('ok', false, 'error', 'invalid_dropoff_mode');
  end if;

  select * into v_listing from public.vehicle_listings where id = p_listing_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'listing_not_found');
  end if;
  if v_listing.seller_id = v_uid then
    return jsonb_build_object('ok', false, 'error', 'cannot_rent_own_vehicle');
  end if;
  if v_listing.status not in ('active') or v_listing.listing_type not in ('rental', 'both') then
    return jsonb_build_object('ok', false, 'error', 'not_rentable');
  end if;

  select * into v_settings from public.vehicle_rental_settings where listing_id = p_listing_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'rental_settings_missing');
  end if;

  v_days := public.vehicle_rental_days(p_pickup_at, p_return_at);
  if v_days < v_settings.min_days or v_days > v_settings.max_days then
    return jsonb_build_object('ok', false, 'error', 'duration_not_allowed', 'days', v_days);
  end if;

  v_subtotal := v_settings.daily_price * v_days;
  if v_settings.weekly_price is not null and v_days >= 7 then
    v_subtotal := least(v_subtotal, v_settings.weekly_price * (v_days / 7.0));
  end if;
  if v_settings.monthly_price is not null and v_days >= 28 then
    v_subtotal := least(v_subtotal, v_settings.monthly_price * (v_days / 30.0));
  end if;
  v_subtotal := round(v_subtotal, 2);

  v_quote := public.quote_vehicle_delivery_fee(p_listing_id, p_delivery_mode, p_lat, p_lng, p_airport);
  if coalesce(v_quote->>'ok', 'false') <> 'true' then
    return v_quote;
  end if;
  v_fee := coalesce((v_quote->>'fee')::numeric, 0);
  v_total := round(v_subtotal + v_fee + coalesce(v_settings.deposit, 0), 2);

  if public.vehicle_rental_window_blocked(p_listing_id, p_pickup_at, p_return_at) then
    return jsonb_build_object('ok', false, 'error', 'not_available');
  end if;

  insert into public.vehicle_reservations (
    listing_id, seller_id, customer_id, status, pickup_at, return_at,
    delivery_mode, delivery_address, delivery_lat, delivery_lng,
    dropoff_mode, dropoff_address, dropoff_lat, dropoff_lng,
    rental_days, rental_subtotal, delivery_fee, deposit, total, payment_status,
    customer_name, customer_phone, customer_birth_date, customer_email,
    customer_note, customer_national_id, cancellation_policy, documents_retention_until
  ) values (
    p_listing_id, v_listing.seller_id, v_uid, 'pending_docs',
    p_pickup_at, p_return_at, p_delivery_mode, p_delivery_address, p_lat, p_lng,
    coalesce(p_dropoff_mode, 'gallery_pickup'), p_dropoff_address, p_dropoff_lat, p_dropoff_lng,
    v_days, v_subtotal, v_fee, coalesce(v_settings.deposit, 0), v_total, 'unpaid',
    p_customer_name, p_customer_phone, p_customer_birth_date, p_customer_email,
    p_customer_note, v_national, v_settings.cancellation_policy,
    timezone('utc', now()) + interval '365 days'
  ) returning id into v_id;

  perform public.vehicle_rental_log_event(v_id, v_uid, 'created', null, 'pending_docs');
  return jsonb_build_object(
    'ok', true,
    'reservation_id', v_id,
    'rental_days', v_days,
    'rental_subtotal', v_subtotal,
    'delivery_fee', v_fee,
    'deposit', coalesce(v_settings.deposit, 0),
    'total', v_total,
    'status', 'pending_docs'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.current_admin_has_module(module_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid;
  current_role text;
  effective_role text;
  allowed_modules text[];
  denied_modules text[];
  catalog_modules text[];
begin
  uid := auth.uid();
  if uid is null or module_key is null or trim(module_key) = '' then
    return false;
  end if;

  select lower(trim(u.role))
  into current_role
  from public.users u
  where u.id = uid
  limit 1;

  if current_role is null then
    return false;
  end if;

  if current_role = 'super_admin' then
    return true;
  end if;

  if not public.is_admin_role(current_role) then
    return false;
  end if;

  select
    lower(trim(coalesce(nullif(trim(a.role_key), ''), u.role))),
    case
      when a.is_active is true
        and cardinality(coalesce(a.allowed_modules, '{}'::text[])) > 0
        then a.allowed_modules
      else null::text[]
    end,
    coalesce(a.denied_modules, '{}'::text[]),
    coalesce(c.modules, '{}'::text[])
  into effective_role, allowed_modules, denied_modules, catalog_modules
  from public.users u
  left join public.admin_user_permissions a
    on a.user_id = u.id and a.is_active = true
  left join public.admin_role_catalog c
    on lower(trim(c.role_key)) = lower(trim(coalesce(nullif(trim(a.role_key), ''), u.role)))
  where u.id = uid
  limit 1;

  denied_modules := coalesce(denied_modules, '{}'::text[]);
  catalog_modules := coalesce(catalog_modules, '{}'::text[]);

  if module_key = any(denied_modules) then
    return false;
  end if;

  -- Genel Operasyon: finance katalogda yoksa bile finance erişimi
  if current_role = 'admin' then
    return module_key = any(catalog_modules) or module_key = 'finance';
  end if;

  if effective_role in ('admin_finance', 'admin_investor') then
    return module_key = 'finance' or module_key = any(catalog_modules);
  end if;

  if allowed_modules is not null and cardinality(allowed_modules) > 0 then
    return module_key = any(allowed_modules);
  end if;

  return module_key = any(catalog_modules);
end;
$function$

CREATE OR REPLACE FUNCTION public.debug_admin_finance_access()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid;
  account_role text;
  permission_role text;
  effective_role text;
  user_email text;
  denied_modules text[];
  allowed_modules text[];
begin
  uid := auth.uid();
  if uid is null then
    return jsonb_build_object('authenticated', false);
  end if;

  select lower(trim(u.role)), u.email
  into account_role, user_email
  from public.users u
  where u.id = uid
  limit 1;

  permission_role := null;
  denied_modules := '{}'::text[];
  allowed_modules := null;

  if to_regclass('public.admin_user_permissions') is not null then
    select
      lower(trim(nullif(trim(a.role_key), ''))),
      coalesce(a.denied_modules, '{}'::text[]),
      a.allowed_modules
    into permission_role, denied_modules, allowed_modules
    from public.admin_user_permissions a
    where a.user_id = uid and a.is_active = true
    limit 1;
  end if;

  effective_role := public.resolve_admin_effective_role(uid);

  return jsonb_build_object(
    'authenticated', true,
    'auth_uid', uid,
    'user_email', user_email,
    'user_role', account_role,
    'permission_role_key', permission_role,
    'effective_role', effective_role,
    'allowed_modules', coalesce(allowed_modules, '{}'::text[]),
    'denied_modules', denied_modules,
    'is_admin_user', public.is_admin_user(uid),
    'admin_can_write_finance', public.admin_can_write_finance(),
    'can_access_finance', public.current_admin_can_access_finance()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_home_feature_campaign_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(new.type, '') <> 'home_feature' then
    return new;
  end if;

  if public.can_bypass_home_feature_status_guard() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'pending_review';
    new.approved_at := null;
    new.rejected_at := null;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.status is distinct from old.status then
      raise exception
        'home_feature kampanya status degisikligi admin onayi gerektirir'
        using errcode = '42501';
    end if;

    if new.approved_at is distinct from old.approved_at
       or new.rejected_at is distinct from old.rejected_at
       or new.review_notes is distinct from old.review_notes then
      raise exception
        'home_feature kampanya inceleme alanlari admin onayi gerektirir'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_ihiz_delivery_task_for_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_item record;
  v_store record;
  v_account public.ihiz_business_accounts%rowtype;
  v_task public.ihiz_delivery_tasks%rowtype;
  v_status text := 'created';
  v_addr jsonb;
  v_delivery_type text;
  v_media text;
begin
  if v_uid is null then
    raise exception 'auth_required';
  end if;
  if p_order_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_order');
  end if;

  select * into v_order from public.orders where id = p_order_id limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'order_not_found');
  end if;

  v_delivery_type := lower(coalesce(v_order.delivery_type, ''));
  if position('ihiz' in v_delivery_type) = 0 and position('kurye' in v_delivery_type) = 0 then
    return jsonb_build_object('ok', false, 'error', 'not_ihiz_delivery');
  end if;

  select *
  into v_item
  from public.order_items
  where order_id = p_order_id
  order by created_at
  limit 1;

  if v_item.seller_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_seller');
  end if;

  if v_order.user_id is distinct from v_uid
     and v_item.seller_id is distinct from v_uid
     and not public.ihiz_actor_is_admin(v_uid) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  select * into v_account
  from public.ihiz_business_accounts
  where seller_id = v_item.seller_id
    and status = 'active'
  limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'business_inactive');
  end if;

  select * into v_store
  from public.stores
  where seller_id = v_item.seller_id
  limit 1;

  v_addr := coalesce(v_order.delivery_address, '{}'::jsonb);

  if lower(coalesce(v_item.status, '')) in ('ready_to_ship') then
    v_status := 'ready_for_pickup';
  elsif lower(coalesce(v_item.status, '')) = 'preparing' then
    v_status := 'preparing';
  elsif lower(coalesce(v_item.status, '')) = 'out_for_delivery' then
    v_status := 'courier_picked_up';
  elsif lower(coalesce(v_item.status, '')) = 'delivered' then
    v_status := 'delivered';
  elsif lower(coalesce(v_item.status, '')) in ('cancelled', 'canceled') then
    v_status := 'cancelled';
  end if;

  select split_part(replace(h.description, 'VIDEO::', ''), '|', 1)
  into v_media
  from public.order_item_status_history h
  where h.order_item_id = v_item.id
    and h.description like 'VIDEO::http%'
  order by h.created_at desc
  limit 1;

  insert into public.ihiz_delivery_tasks (
    order_id,
    seller_id,
    store_id,
    created_by_user_id,
    source_type,
    tracking_code,
    status,
    pickup_name,
    pickup_phone,
    pickup_address,
    pickup_city,
    pickup_district,
    pickup_lat,
    pickup_lng,
    dropoff_name,
    dropoff_phone,
    dropoff_address,
    dropoff_city,
    dropoff_district,
    dropoff_lat,
    dropoff_lng,
    notes,
    package_media_url
  ) values (
    p_order_id,
    v_item.seller_id,
    v_item.seller_id,
    v_uid,
    'ibul_order',
    public.ihiz_generate_tracking_code(),
    v_status,
    v_store.business_name,
    coalesce(v_store.support_phone, v_store.phone),
    v_store.address,
    v_store.city,
    v_store.district,
    v_store.store_lat,
    v_store.store_lng,
    coalesce(v_addr->>'fullName', v_addr->>'name'),
    coalesce(v_addr->>'phone', v_addr->>'phoneNumber'),
    coalesce(v_addr->>'address', v_addr->>'detail'),
    v_addr->>'city',
    v_addr->>'district',
    case
      when coalesce(v_addr->>'lat', v_addr->>'latitude', '') ~ '^-?[0-9]+(\\.[0-9]+)?$'
      then coalesce(v_addr->>'lat', v_addr->>'latitude')::double precision
      else null
    end,
    case
      when coalesce(v_addr->>'lng', v_addr->>'longitude', '') ~ '^-?[0-9]+(\\.[0-9]+)?$'
      then coalesce(v_addr->>'lng', v_addr->>'longitude')::double precision
      else null
    end,
    v_addr->>'note',
    nullif(trim(v_media), '')
  )
  on conflict (order_id) where order_id is not null
  do update set
    status = case
      when public.ihiz_delivery_tasks.status in ('delivered', 'cancelled') then public.ihiz_delivery_tasks.status
      else excluded.status
    end,
    package_media_url = coalesce(
      public.ihiz_delivery_tasks.package_media_url,
      excluded.package_media_url
    ),
    updated_at = timezone('utc', now())
  returning * into v_task;

  if not exists (
    select 1
    from public.ihiz_delivery_events e
    where e.delivery_task_id = v_task.id
      and e.event_type = 'created'
  ) then
    perform public.ihiz_append_delivery_event(
      v_task.id,
      'created',
      'created',
      'Sipariş İHIZ teslimatına alındı',
      'İBUL siparişi için teslimat görevi oluşturuldu.',
      'seller',
      v_uid,
      jsonb_build_object('order_number', v_order.order_number)
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'id', v_task.id,
    'tracking_code', v_task.tracking_code,
    'status', v_task.status,
    'duplicate', false
  );
exception
  when unique_violation then
    select * into v_task
    from public.ihiz_delivery_tasks
    where order_id = p_order_id
    limit 1;
    return jsonb_build_object(
      'ok', true,
      'id', v_task.id,
      'tracking_code', v_task.tracking_code,
      'status', v_task.status,
      'duplicate', true
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_store_business_serial_no(p_store_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_store uuid := coalesce(p_store_id, v_uid);
  v_code text;
  v_name text;
  v_status text;
begin
  if v_uid is null then
    raise exception 'auth_required';
  end if;
  if v_store is null then
    raise exception 'store_forbidden';
  end if;
  if not (
    public.ihiz_actor_owns_store(v_store, v_uid)
    or public.ihiz_actor_is_admin(v_uid)
  ) then
    raise exception 'store_forbidden';
  end if;

  insert into public.store_business_serials (store_id, business_serial_no)
  values (v_store, public.ihiz_generate_business_serial())
  on conflict (store_id) do nothing;

  select serials.business_serial_no, s.business_name
  into v_code, v_name
  from public.store_business_serials serials
  join public.stores s on s.seller_id = serials.store_id
  where serials.store_id = v_store
  limit 1;

  select a.status
  into v_status
  from public.ihiz_business_accounts a
  where a.store_id = v_store
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'store_id', v_store,
    'business_serial_no', v_code,
    'business_name', v_name,
    'ihiz_status', v_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_unpaid_vehicle_rentals()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.vehicle_reservations%rowtype;
  v_count int := 0;
  v_title text;
  v_code text;
begin
  for r in
    select *
    from public.vehicle_reservations
    where status = 'pending_payment'
      and coalesce(payment_status, 'unpaid') not in ('paid', 'authorized')
      and payment_due_at is not null
      and payment_due_at <= timezone('utc', now())
    for update skip locked
  loop
    update public.vehicle_reservations
    set status = 'cancelled',
        cancel_reason = 'payment_window_expired',
        cancel_actor = 'system',
        cancelled_at = timezone('utc', now())
    where id = r.id
      and status = 'pending_payment'
      and coalesce(payment_status, 'unpaid') not in ('paid', 'authorized');
    if not found then
      continue;
    end if;
    v_count := v_count + 1;
    v_title := public.vehicle_rental_listing_title(r.listing_id);
    v_code := coalesce(r.rental_code, 'IBR-XXXX');
    perform public.vehicle_rental_notify(
      r.customer_id,
      'Kiralama talebi iptal edildi',
      'Ödeme süresi dolduğu için kiralama talebiniz iptal edildi.',
      'vehicle_rental_payment_expired',
      jsonb_build_object(
        'reservation_id', r.id,
        'rental_code', r.rental_code,
        'listing_title', v_title
      )
    );
    perform public.vehicle_rental_notify(
      r.seller_id,
      'Kiralama otomatik iptal',
      v_code || ' numaralı kiralama talebi ödeme yapılmadığı için otomatik iptal edildi.',
      'vehicle_rental_payment_expired',
      jsonb_build_object(
        'reservation_id', r.id,
        'rental_code', r.rental_code,
        'listing_title', v_title,
        'audience', 'seller'
      )
    );
    perform public.vehicle_rental_log_event(
      r.id, null, 'payment_window_expired', 'pending_payment', 'cancelled'
    );
  end loop;
  return jsonb_build_object('ok', true, 'expired', v_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.flatten_waiter_items_for_kitchen_print(p_seller_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  out jsonb := '[]'::jsonb;
  el jsonb;
  typ text;
  qty int;
  pid text;
  pr record;
  nm text;
  note text;
  children jsonb;
  child_rec record;
  child_qty int;
  parent_qty int;
  unit_p numeric;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return '[]'::jsonb;
  end if;

  for el in select value from jsonb_array_elements(p_items)
  loop
    typ := lower(coalesce(el.value ->> 'type', ''));
    if typ = 'waiter_call' then
      continue;
    end if;

    if lower(coalesce(el.value ->> 'item_type', '')) = 'mixed_service' then
      parent_qty := greatest(coalesce((el.value ->> 'quantity')::int, 1), 1);
      children := coalesce(el.value -> 'child_items', '[]'::jsonb);
      if jsonb_typeof(children) = 'array' then
        for child_rec in select jsonb_array_elements(children) as j
        loop
          child_qty := greatest(coalesce((child_rec.j ->> 'quantity')::int, 1), 1);
          pid := coalesce(
            nullif(trim(child_rec.j ->> 'product_id'), ''),
            nullif(trim(child_rec.j ->> 'productId'), '')
          );
          continue when pid is null or pid = '';
          select * into pr from public._waiter_req_product_row(p_seller_id, pid);
          if not found then
            continue;
          end if;
          nm := coalesce(
            nullif(trim(child_rec.j ->> 'product_name'), ''),
            nullif(trim(child_rec.j ->> 'name'), ''),
            pr.name
          );
          unit_p := public._waiter_req_simple_unit_price(
            p_seller_id,
            jsonb_build_object(
              'productId', pid,
              'selectedSizeName', child_rec.j ->> 'selected_size_name',
              'selectedWeightGrams', child_rec.j ->> 'selected_weight_grams',
              'selectedServiceAmount', child_rec.j ->> 'selected_service_amount'
            )
          );
          note := coalesce(
            nullif(trim(child_rec.j ->> 'notes'), ''),
            nullif(trim(child_rec.j ->> 'note'), ''),
            nullif(trim(el.value ->> 'notes'), '')
          );
          out := out || jsonb_build_array(
            jsonb_build_object(
              'product_id', pid,
              'name', nm,
              'quantity', child_qty * parent_qty,
              'price', unit_p,
              'notes', note,
              'station_id', pr.station_id::text
            )
          );
        end loop;
      end if;
      continue;
    end if;

    pid := coalesce(
      nullif(trim(el.value ->> 'productId'), ''),
      nullif(trim(el.value ->> 'product_id'), '')
    );
    continue when pid is null or pid = '';
    qty := greatest(coalesce((el.value ->> 'quantity')::int, 1), 1);
    select * into pr from public._waiter_req_product_row(p_seller_id, pid);
    continue when not found;
    nm := coalesce(nullif(trim(el.value ->> 'name'), ''), pr.name);
    unit_p := (el.value ->> 'price')::numeric;
    if unit_p is null then
      unit_p := public._waiter_req_simple_unit_price(p_seller_id, el.value);
    end if;
    note := coalesce(
      nullif(trim(el.value ->> 'notes'), ''),
      nullif(trim(el.value ->> 'note'), '')
    );
    out := out || jsonb_build_array(
      jsonb_build_object(
        'product_id', pid,
        'name', nm,
        'quantity', qty,
        'price', unit_p,
        'notes', note,
        'station_id', pr.station_id::text
      )
    );
  end loop;

  return out;
end;
$function$

CREATE OR REPLACE FUNCTION public.follow_store(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if not exists (select 1 from public.stores where seller_id = p_store_id) then
    raise exception 'store_not_found';
  end if;

  insert into public.store_followers(store_id, user_id)
  values (p_store_id, v_user_id)
  on conflict (store_id, user_id) do nothing;

  select follower_count into v_count
  from public.stores
  where seller_id = p_store_id;

  return jsonb_build_object(
    'is_following', true,
    'notifications_enabled', coalesce((
      select snp.enabled
      from public.store_notification_preferences snp
      where snp.store_id = p_store_id and snp.user_id = v_user_id
    ), false),
    'follower_count', coalesce(v_count, 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_ihiz_public_tracking(p_tracking_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := public.ihiz_normalize_tracking_code(p_tracking_code);
  v_hash text;
  v_addr inet := inet_client_addr();
  v_recent int := 0;
  v_task public.ihiz_delivery_tasks%rowtype;
  v_live boolean := false;
  v_events jsonb := '[]'::jsonb;
  v_store_name text;
begin
  if v_code is null or v_code = '' or v_code !~ '^IHZ-[A-Z0-9]{6}$' then
    return jsonb_build_object('found', false, 'error', 'not_found');
  end if;

  v_hash := encode(digest(v_code, 'sha256'), 'hex');
  insert into public.ihiz_tracking_lookup_log (tracking_code_hash, client_addr)
  values (v_hash, v_addr);

  select count(*)::int
  into v_recent
  from public.ihiz_tracking_lookup_log
  where created_at > timezone('utc', now()) - interval '10 minutes'
    and (
      (v_addr is not null and client_addr = v_addr)
      or (v_addr is null and client_addr is null and tracking_code_hash = v_hash)
    );

  if v_recent > 40 then
    return jsonb_build_object('found', false, 'error', 'rate_limited');
  end if;

  select *
  into v_task
  from public.ihiz_delivery_tasks
  where tracking_code = v_code
  limit 1;

  if not found then
    return jsonb_build_object('found', false, 'error', 'not_found');
  end if;

  v_live := v_task.status in ('courier_picked_up', 'in_transit');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'event_type', e.event_type,
        'status', e.status,
        'title', e.title,
        'description', e.description,
        'created_at', e.created_at
      )
      order by e.created_at
    ),
    '[]'::jsonb
  )
  into v_events
  from public.ihiz_delivery_events e
  where e.delivery_task_id = v_task.id;

  if v_task.store_id is not null then
    select s.business_name
    into v_store_name
    from public.stores s
    where s.seller_id = v_task.store_id
    limit 1;
  end if;

  return jsonb_build_object(
    'found', true,
    'tracking_code', v_task.tracking_code,
    'status', v_task.status,
    'source_type', v_task.source_type,
    'created_at', v_task.created_at,
    'picked_up_at', v_task.picked_up_at,
    'delivered_at', v_task.delivered_at,
    'cancelled_at', v_task.cancelled_at,
    'package_size', v_task.package_size,
    'package_weight', v_task.package_weight,
    'notes', case
      when v_task.notes is null then null
      when length(v_task.notes) > 180 then left(v_task.notes, 180)
      else v_task.notes
    end,
    'package_media_url', v_task.package_media_url,
    'sender_name', coalesce(nullif(v_store_name, ''), v_task.pickup_name),
    'pickup_label', nullif(trim(both from concat_ws(' / ', v_task.pickup_city, v_task.pickup_district)), ''),
    'dropoff_label', nullif(trim(both from concat_ws(' / ', v_task.dropoff_city, v_task.dropoff_district)), ''),
    'live', case
      when v_live then jsonb_build_object(
        'courier_lat', v_task.courier_lat,
        'courier_lng', v_task.courier_lng,
        'courier_location_updated_at', v_task.courier_location_updated_at,
        'pickup_lat', v_task.pickup_lat,
        'pickup_lng', v_task.pickup_lng,
        'dropoff_lat', v_task.dropoff_lat,
        'dropoff_lng', v_task.dropoff_lng
      )
      else null
    end,
    'events', v_events
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_reward_wheel_for_user()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_config public.reward_wheel_configs%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_items jsonb;
  v_elig jsonb;
  v_can boolean := false;
begin
  select * into v_config
  from public.reward_wheel_configs
  where is_active = true
  order by updated_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'is_active', false,
      'can_spin', false,
      'items', '[]'::jsonb
    );
  end if;

  v_elig := public.reward_wheel_user_eligibility(auth.uid(), v_config, v_now);
  if v_elig->>'reason' in ('inactive', 'not_started', 'ended') then
    return jsonb_build_object(
      'ok', true,
      'id', v_config.id,
      'is_active', false,
      'can_spin', false,
      'eligibility_reason', v_elig->>'reason',
      'next_spin_at', v_elig->>'next_spin_at',
      'items', '[]'::jsonb
    );
  end if;

  v_items := public.reward_wheel_compose_for_user(auth.uid(), v_config);
  v_can := coalesce((v_elig->>'can_spin')::boolean, false)
    and coalesce(jsonb_array_length(v_items), 0) > 0;

  return jsonb_build_object(
    'ok', true,
    'id', v_config.id,
    'is_active', true,
    'can_spin', v_can,
    'eligibility_reason', v_elig->>'reason',
    'next_spin_at', v_elig->>'next_spin_at',
    'daily_free_spins', v_config.daily_free_spins,
    'per_user_daily_limit', v_config.per_user_daily_limit,
    'cooldown_hours', v_config.cooldown_hours,
    'use_global_pool', v_config.use_global_pool,
    'items', coalesce(v_items, '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_store_follow_state(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_following boolean := false;
  v_notifications boolean := false;
  v_count integer := 0;
begin
  select coalesce(follower_count, 0) into v_count
  from public.stores
  where seller_id = p_store_id;

  if v_user_id is not null then
    v_following := exists (
      select 1 from public.store_followers
      where store_id = p_store_id and user_id = v_user_id
    );

    v_notifications := exists (
      select 1 from public.store_notification_preferences snp
      where snp.store_id = p_store_id
        and snp.user_id = v_user_id
        and snp.enabled = true
    );
  end if;

  return jsonb_build_object(
    'is_following', v_following,
    'notifications_enabled', v_notifications,
    'follower_count', coalesce(v_count, 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hybrid_delivery_confirm_option(p_actor_user_id uuid, p_order_id text, p_quote_id uuid, p_option_id uuid, p_selected_branch_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote public.delivery_quotes%rowtype;
  v_option public.delivery_options%rowtype;
  v_allowed boolean := false;
  v_order_exists boolean := false;
  v_updated_count bigint := 0;
begin
  if p_actor_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'actor_required');
  end if;

  select *
  into v_quote
  from public.delivery_quotes
  where id = p_quote_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'quote_not_found');
  end if;

  select *
  into v_option
  from public.delivery_options
  where id = p_option_id
    and quote_id = p_quote_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'option_not_found');
  end if;

  if not v_option.is_available then
    return jsonb_build_object('ok', false, 'error', 'option_not_available', 'reason', v_option.reason_code);
  end if;

  v_allowed := (
    p_actor_user_id = v_quote.seller_id
    or p_actor_user_id = v_quote.user_id
    or public.delivery_is_admin(p_actor_user_id)
  );

  if not v_allowed then
    return jsonb_build_object('ok', false, 'error', 'not_authorized');
  end if;

  if to_regclass('public.orders') is not null then
    update public.orders
    set
      shipment_type = v_option.shipment_type,
      selected_branch_id = coalesce(p_selected_branch_id, v_option.selected_branch_id),
      customer_delivery_fee = coalesce(v_option.customer_delivery_fee, 0),
      seller_delivery_fee = coalesce(v_option.seller_delivery_fee, 0),
      distance_km = v_quote.distance_km,
      branch_distance_km = v_option.branch_distance_km,
      delivery_quote_id = v_quote.id,
      total_delivery_fee = coalesce(v_option.delivery_fee, 0),
      updated_at = timezone('utc', now())
    where id::text = p_order_id;

    get diagnostics v_updated_count = row_count;
    v_order_exists := v_updated_count > 0;
  end if;

  return jsonb_build_object(
    'ok', true,
    'order_updated', v_order_exists,
    'order_id', p_order_id,
    'quote_id', v_quote.id,
    'selected_option_id', v_option.id,
    'shipment_type', v_option.shipment_type,
    'delivery_fee', v_option.delivery_fee,
    'customer_delivery_fee', v_option.customer_delivery_fee,
    'seller_delivery_fee', v_option.seller_delivery_fee,
    'seller_id', v_quote.seller_id,
    'source', v_quote.source
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hybrid_delivery_quote(p_actor_user_id uuid, p_source text, p_seller_id uuid, p_customer_address jsonb, p_weather text DEFAULT 'clear'::text, p_is_night boolean DEFAULT false, p_surge_level text DEFAULT 'normal'::text, p_payer_mode payer_mode DEFAULT 'seller_pays'::payer_mode, p_selected_company_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
  v_config jsonb := '{}'::jsonb;

  v_nearby_threshold numeric := 8;
  v_medium_threshold numeric := 20;
  v_direct_max_distance numeric := 20;
  v_direct_base_fee numeric := 28;
  v_direct_km_fee numeric := 7;
  v_platform_fee numeric := 10;
  v_branch_base_fee numeric := 20;
  v_branch_km_fee numeric := 6;
  v_min_fee numeric := 35;
  v_max_fee numeric := 350;

  v_minute_price numeric := 4;
  v_eta_per_km_minute numeric := 5;
  v_eta_base_minute numeric := 6;
  v_night_bonus numeric := 12;
  v_rain_bonus numeric := 15;
  v_storm_bonus numeric := 20;
  v_snow_bonus numeric := 25;
  v_multi_order_bonus numeric := 25;

  v_active_cities_csv text := '';
  v_enabled_companies_csv text := '';

  v_seller_lat double precision;
  v_seller_lng double precision;
  v_customer_lat double precision;
  v_customer_lng double precision;

  v_distance_km numeric;
  v_eta_minutes numeric;
  v_surge_multiplier numeric := 1.0;
  v_weather_bonus numeric := 0;

  v_direct_available boolean := false;
  v_standard_available boolean := false;
  v_branch_available boolean := false;
  v_city_allowed boolean := true;

  v_recommended public.shipment_type := 'standard_cargo';
  v_customer_address_id uuid;
  v_quote_id uuid;

  v_direct_courier_fee numeric := 0;
  v_direct_total numeric := 0;
  v_direct_customer_fee numeric := 0;
  v_direct_seller_fee numeric := 0;

  v_branch_distance_km numeric := null;
  v_branch_total numeric := null;
  v_branch_customer_fee numeric := null;
  v_branch_seller_fee numeric := null;
  v_branch_id uuid := null;

  v_customer_tier_fee numeric := 0;
  v_options jsonb := '[]'::jsonb;
  v_selected_city text := null;
begin
  if p_actor_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'actor_required');
  end if;
  if p_seller_id is null then
    return jsonb_build_object('ok', false, 'error', 'seller_required');
  end if;
  if p_customer_address is null then
    return jsonb_build_object('ok', false, 'error', 'customer_address_required');
  end if;

  select config
  into v_config
  from public.ihiz_pricing_rule_versions
  where is_active = true
  order by version desc
  limit 1;

  v_nearby_threshold := public.delivery_jsonb_get_numeric(v_config, 'nearby_threshold_km', 8);
  v_medium_threshold := public.delivery_jsonb_get_numeric(v_config, 'medium_distance_threshold_km', 20);
  v_direct_max_distance := public.delivery_jsonb_get_numeric(v_config, 'ihiz_direct_max_distance_km', 20);
  v_direct_base_fee := public.delivery_jsonb_get_numeric(v_config, 'base_fee', 28);
  v_direct_km_fee := public.delivery_jsonb_get_numeric(v_config, 'per_km_fee', 7);
  v_platform_fee := public.delivery_jsonb_get_numeric(v_config, 'platform_fee', 10);
  v_branch_base_fee := public.delivery_jsonb_get_numeric(v_config, 'branch_base_fee', 20);
  v_branch_km_fee := public.delivery_jsonb_get_numeric(v_config, 'branch_km_fee', 6);
  v_min_fee := public.delivery_jsonb_get_numeric(v_config, 'min_delivery_fee', 35);
  v_max_fee := public.delivery_jsonb_get_numeric(v_config, 'max_delivery_fee', 350);
  v_minute_price := public.delivery_jsonb_get_numeric(v_config, 'courier_minute_price', 4);
  v_eta_per_km_minute := public.delivery_jsonb_get_numeric(v_config, 'eta_per_km_minute', 5);
  v_eta_base_minute := public.delivery_jsonb_get_numeric(v_config, 'eta_base_minute', 6);
  v_night_bonus := public.delivery_jsonb_get_numeric(v_config, 'courier_night_bonus', 12);
  v_rain_bonus := public.delivery_jsonb_get_numeric(v_config, 'courier_rain_bonus', 15);
  v_storm_bonus := public.delivery_jsonb_get_numeric(v_config, 'courier_storm_bonus', 20);
  v_snow_bonus := public.delivery_jsonb_get_numeric(v_config, 'courier_snow_bonus', 25);
  v_multi_order_bonus := public.delivery_jsonb_get_numeric(v_config, 'courier_multi_order_bonus', 25);

  v_active_cities_csv := coalesce(v_config ->> 'ihiz_active_cities', '');
  v_enabled_companies_csv := coalesce(v_config ->> 'enabled_cargo_companies', '');

  select
    coalesce(sl.latitude, s.store_lat),
    coalesce(sl.longitude, s.store_lng)
  into v_seller_lat, v_seller_lng
  from public.users u
  left join public.seller_locations sl on sl.seller_id = u.id and sl.is_active = true
  left join public.stores s on s.seller_id = u.id
  where u.id = p_seller_id
  limit 1;

  if v_seller_lat is null or v_seller_lng is null then
    return jsonb_build_object('ok', false, 'error', 'seller_location_missing');
  end if;

  begin
    v_customer_lat := coalesce(
      nullif(trim(coalesce(p_customer_address ->> 'lat', '')), '')::double precision,
      nullif(trim(coalesce(p_customer_address ->> 'latitude', '')), '')::double precision
    );
    v_customer_lng := coalesce(
      nullif(trim(coalesce(p_customer_address ->> 'lng', '')), '')::double precision,
      nullif(trim(coalesce(p_customer_address ->> 'longitude', '')), '')::double precision
    );
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_coordinates');
  end;

  if v_customer_lat is null or v_customer_lng is null then
    return jsonb_build_object('ok', false, 'error', 'customer_coordinates_missing');
  end if;

  v_selected_city := coalesce(
    nullif(trim(coalesce(p_customer_address ->> 'city', '')), ''),
    nullif(trim(coalesce(p_customer_address ->> 'il', '')), '')
  );

  if trim(v_active_cities_csv) <> '' and v_selected_city is not null then
    v_city_allowed := lower(v_selected_city) = any(
      string_to_array(lower(replace(v_active_cities_csv, ' ', '')), ',')
    );
  end if;

  insert into public.addresses(
    formatted_address,
    city,
    district,
    latitude,
    longitude,
    place_id,
    created_by
  ) values (
    coalesce(nullif(trim(coalesce(p_customer_address ->> 'formatted_address', '')), ''), 'Adres'),
    v_selected_city,
    nullif(trim(coalesce(p_customer_address ->> 'district', '')), ''),
    v_customer_lat,
    v_customer_lng,
    nullif(trim(coalesce(p_customer_address ->> 'place_id', '')), ''),
    p_actor_user_id
  ) returning id into v_customer_address_id;

  if p_source = 'ibul_checkout' then
    insert into public.user_saved_addresses(user_id, address_id, label, is_default)
    values (
      p_actor_user_id,
      v_customer_address_id,
      nullif(trim(coalesce(p_customer_address ->> 'label', '')), ''),
      coalesce((p_customer_address ->> 'is_default')::boolean, false)
    )
    on conflict (user_id, address_id) do nothing;
  end if;

  v_distance_km := public.delivery_geo_distance_km(v_seller_lat, v_seller_lng, v_customer_lat, v_customer_lng);
  v_distance_km := round(greatest(v_distance_km, 0)::numeric, 3);
  v_eta_minutes := round((v_eta_base_minute + (v_distance_km * v_eta_per_km_minute))::numeric, 2);

  case lower(coalesce(p_surge_level, 'normal'))
    when 'medium' then v_surge_multiplier := 1.2;
    when 'high' then v_surge_multiplier := 1.4;
    else v_surge_multiplier := 1.0;
  end case;

  case lower(coalesce(p_weather, 'clear'))
    when 'rain' then v_weather_bonus := v_rain_bonus;
    when 'storm' then v_weather_bonus := v_storm_bonus;
    when 'snow' then v_weather_bonus := v_snow_bonus;
    else v_weather_bonus := 0;
  end case;

  if v_distance_km <= v_nearby_threshold then
    v_direct_available := true;
    v_standard_available := false;
    v_branch_available := false;
    v_recommended := 'ihiz_direct';
  elsif v_distance_km <= v_medium_threshold then
    v_direct_available := true;
    v_standard_available := true;
    v_branch_available := false;
    v_recommended := 'ihiz_direct';
  else
    v_direct_available := false;
    v_standard_available := true;
    v_branch_available := true;
    v_recommended := 'standard_cargo';
  end if;

  if v_distance_km > v_direct_max_distance then
    v_direct_available := false;
    if v_recommended = 'ihiz_direct' then
      v_recommended := 'standard_cargo';
    end if;
  end if;

  if not v_city_allowed then
    v_direct_available := false;
    v_branch_available := false;
    v_recommended := 'standard_cargo';
  end if;

  if v_direct_available then
    v_direct_courier_fee := greatest(
      v_direct_base_fee + (v_distance_km * v_direct_km_fee),
      v_eta_minutes * v_minute_price
    );
    v_direct_courier_fee := (v_direct_courier_fee * v_surge_multiplier)
      + case when p_is_night then v_night_bonus else 0 end
      + v_weather_bonus;

    v_direct_total := v_direct_courier_fee + v_platform_fee;
    v_direct_total := least(greatest(v_direct_total, v_min_fee), v_max_fee);

    if p_payer_mode = 'customer_pays' then
      v_direct_customer_fee := v_direct_total;
      v_direct_seller_fee := 0;
    elsif p_payer_mode = 'hybrid' then
      if v_distance_km <= 3 then
        v_customer_tier_fee := public.delivery_jsonb_get_numeric(v_config, 'customer_fee_0_3_km', 35);
      elsif v_distance_km <= 6 then
        v_customer_tier_fee := public.delivery_jsonb_get_numeric(v_config, 'customer_fee_3_6_km', 45);
      else
        v_customer_tier_fee := public.delivery_jsonb_get_numeric(v_config, 'customer_fee_6_plus_km', 55);
      end if;
      v_direct_customer_fee := least(v_direct_total, v_customer_tier_fee);
      v_direct_seller_fee := greatest(v_direct_total - v_direct_customer_fee, 0);
    else
      v_direct_customer_fee := 0;
      v_direct_seller_fee := v_direct_total;
    end if;
  end if;

  if v_branch_available then
    if p_selected_company_id is not null then
      select
        b.id,
        public.delivery_geo_distance_km(v_seller_lat, v_seller_lng, b.latitude, b.longitude)
      into v_branch_id, v_branch_distance_km
      from public.cargo_branches b
      join public.cargo_companies c on c.id = b.company_id
      where b.company_id = p_selected_company_id
        and b.is_active = true
        and c.is_enabled = true
        and (
          trim(v_enabled_companies_csv) = ''
          or lower(c.code) = any(string_to_array(lower(replace(v_enabled_companies_csv, ' ', '')), ','))
        )
      order by public.delivery_geo_distance_km(v_seller_lat, v_seller_lng, b.latitude, b.longitude)
      limit 1;
    end if;

    if v_branch_id is not null then
      v_branch_total := round((v_branch_base_fee + (v_branch_distance_km * v_branch_km_fee))::numeric, 2);
      if p_payer_mode = 'customer_pays' then
        v_branch_customer_fee := v_branch_total;
        v_branch_seller_fee := 0;
      elsif p_payer_mode = 'hybrid' then
        v_branch_customer_fee := least(v_branch_total, public.delivery_jsonb_get_numeric(v_config, 'customer_fee_0_3_km', 35));
        v_branch_seller_fee := greatest(v_branch_total - v_branch_customer_fee, 0);
      else
        v_branch_customer_fee := 0;
        v_branch_seller_fee := v_branch_total;
      end if;
    end if;
  end if;

  insert into public.delivery_quotes(
    seller_id,
    user_id,
    source,
    payer_mode,
    customer_address_id,
    distance_km,
    eta_minutes,
    recommended_type,
    expires_at
  )
  values (
    p_seller_id,
    case when p_source = 'ibul_checkout' then p_actor_user_id else null end,
    p_source,
    p_payer_mode,
    v_customer_address_id,
    v_distance_km,
    v_eta_minutes,
    v_recommended,
    v_now + interval '15 minutes'
  )
  returning id into v_quote_id;

  insert into public.delivery_options(
    quote_id,
    shipment_type,
    is_available,
    reason_code,
    delivery_fee,
    courier_fee,
    platform_fee,
    customer_delivery_fee,
    seller_delivery_fee,
    surge_multiplier,
    weather_bonus,
    night_bonus,
    multi_order_bonus,
    distance_km,
    eta_minutes,
    metadata
  ) values (
    v_quote_id,
    'ihiz_direct',
    v_direct_available,
    case
      when not v_city_allowed then 'city_not_active'
      when v_distance_km > v_direct_max_distance then 'exceeds_direct_max_distance'
      when v_distance_km > v_medium_threshold then 'distance_over_medium_threshold'
      else null
    end,
    case when v_direct_available then round(v_direct_total::numeric, 2) else null end,
    case when v_direct_available then round(v_direct_courier_fee::numeric, 2) else null end,
    case when v_direct_available then round(v_platform_fee::numeric, 2) else null end,
    case when v_direct_available then round(v_direct_customer_fee::numeric, 2) else null end,
    case when v_direct_available then round(v_direct_seller_fee::numeric, 2) else null end,
    round(v_surge_multiplier::numeric, 2),
    round(v_weather_bonus::numeric, 2),
    round((case when p_is_night then v_night_bonus else 0 end)::numeric, 2),
    round(v_multi_order_bonus::numeric, 2),
    v_distance_km,
    v_eta_minutes,
    jsonb_build_object('type', 'ihiz_direct')
  );

  insert into public.delivery_options(
    quote_id,
    shipment_type,
    is_available,
    reason_code,
    metadata
  ) values (
    v_quote_id,
    'standard_cargo',
    v_standard_available,
    case
      when v_distance_km <= v_nearby_threshold then 'prefer_ihiz_direct_for_nearby'
      else null
    end,
    jsonb_build_object('note', 'seller_contract_cargo')
  );

  insert into public.delivery_options(
    quote_id,
    shipment_type,
    is_available,
    reason_code,
    delivery_fee,
    courier_fee,
    platform_fee,
    customer_delivery_fee,
    seller_delivery_fee,
    distance_km,
    eta_minutes,
    branch_distance_km,
    selected_branch_id,
    metadata
  ) values (
    v_quote_id,
    'ihiz_to_branch',
    v_branch_available,
    case
      when not v_city_allowed then 'city_not_active'
      when v_distance_km <= v_medium_threshold then 'only_for_long_distance'
      when v_branch_id is null then 'branch_not_selected_or_not_found'
      else null
    end,
    case when v_branch_available and v_branch_total is not null then round(v_branch_total::numeric, 2) else null end,
    case when v_branch_available and v_branch_total is not null then round(v_branch_total::numeric, 2) else null end,
    0,
    case when v_branch_available then round(coalesce(v_branch_customer_fee, 0)::numeric, 2) else null end,
    case when v_branch_available then round(coalesce(v_branch_seller_fee, 0)::numeric, 2) else null end,
    v_distance_km,
    v_eta_minutes,
    case when v_branch_distance_km is not null then round(v_branch_distance_km::numeric, 3) else null end,
    v_branch_id,
    jsonb_build_object(
      'type', 'ihiz_to_branch',
      'branch_base_fee', v_branch_base_fee,
      'branch_km_fee', v_branch_km_fee
    )
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'option_id', o.id,
        'shipment_type', o.shipment_type,
        'is_available', o.is_available,
        'reason_code', o.reason_code,
        'delivery_fee', o.delivery_fee,
        'courier_fee', o.courier_fee,
        'platform_fee', o.platform_fee,
        'customer_delivery_fee', o.customer_delivery_fee,
        'seller_delivery_fee', o.seller_delivery_fee,
        'surge_multiplier', o.surge_multiplier,
        'weather_bonus', o.weather_bonus,
        'night_bonus', o.night_bonus,
        'distance_km', o.distance_km,
        'eta_minutes', o.eta_minutes,
        'branch_distance_km', o.branch_distance_km,
        'selected_branch_id', o.selected_branch_id,
        'metadata', o.metadata
      )
      order by
        case o.shipment_type
          when 'ihiz_direct' then 1
          when 'standard_cargo' then 2
          else 3
        end
    ),
    '[]'::jsonb
  )
  into v_options
  from public.delivery_options o
  where o.quote_id = v_quote_id;

  update public.delivery_quotes
  set options = v_options,
      recommended_type = v_recommended
  where id = v_quote_id;

  return jsonb_build_object(
    'ok', true,
    'quote_id', v_quote_id,
    'distance_km', v_distance_km,
    'eta_minutes', v_eta_minutes,
    'recommended_type', v_recommended,
    'options', v_options
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ihiz_delivery_task_can_access(p_task ihiz_delivery_tasks, target_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if target_user_id is null then
    return false;
  end if;
  if public.ihiz_actor_is_admin(target_user_id) then
    return true;
  end if;
  if p_task.seller_id = target_user_id or p_task.created_by_user_id = target_user_id then
    return true;
  end if;
  if p_task.assigned_courier_id = target_user_id then
    return true;
  end if;
  if p_task.store_id is not null and public.ihiz_actor_owns_store(p_task.store_id, target_user_id) then
    return true;
  end if;
  if public.ihiz_actor_is_approved_courier(target_user_id)
     and p_task.status in ('created', 'preparing', 'ready_for_pickup')
     and p_task.assigned_courier_id is null then
    if p_task.store_id is null then
      return true;
    end if;
    if exists (
      select 1
      from public.ihiz_store_couriers sc
      where sc.store_id = p_task.store_id
        and sc.is_selected = true
        and sc.is_active = true
    ) then
      return exists (
        select 1
        from public.ihiz_store_couriers sc
        where sc.store_id = p_task.store_id
          and sc.courier_user_id = target_user_id
          and sc.is_selected = true
          and sc.is_active = true
      );
    end if;
    return true;
  end if;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.increment_home_feature_metric(p_campaign_id text, p_metric_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_path text[];
begin
  if to_regclass('public.campaigns') is null then
    return;
  end if;

  if p_metric_key not in (
    'impressions_count',
    'banner_clicks_count',
    'profile_opens_count',
    'product_clicks_count',
    'favorites_count',
    'message_clicks_count'
  ) then
    return;
  end if;

  v_path := array['home_metrics', p_metric_key];
  update public.campaigns
  set metadata = jsonb_set(
    coalesce(metadata, '{}'::jsonb),
    v_path,
    to_jsonb(coalesce((metadata #>> v_path)::int, 0) + 1),
    true
  ),
  updated_at = now()
  where id = p_campaign_id
    and type = 'home_feature';
end;
$function$

CREATE OR REPLACE FUNCTION public.is_admin_user(target_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  role_key text;
begin
  if target_user_id is null then
    return false;
  end if;
  if to_regclass('public.users') is null then
    return false;
  end if;

  select u.role
  into role_key
  from public.users u
  where u.id = target_user_id
  limit 1;

  return public.is_admin_role(role_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.link_ihiz_business_by_serial(p_serial text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_code text := public.ihiz_normalize_business_serial(p_serial);
  v_store_id uuid;
  v_name text;
  v_row public.ihiz_business_accounts%rowtype;
begin
  if v_uid is null then
    raise exception 'auth_required';
  end if;
  if v_code is null or v_code !~ '^ISL-[A-Z0-9]{6}$' then
    raise exception 'not_found';
  end if;

  select serials.store_id, s.business_name
  into v_store_id, v_name
  from public.store_business_serials serials
  join public.stores s on s.seller_id = serials.store_id
  where serials.business_serial_no = v_code
  limit 1;

  if v_store_id is null then
    raise exception 'not_found';
  end if;
  if v_store_id <> v_uid then
    raise exception 'store_forbidden';
  end if;

  insert into public.ihiz_business_accounts (
    seller_id, store_id, status, business_name, activated_at
  ) values (
    v_uid, v_store_id, 'active', v_name, timezone('utc', now())
  )
  on conflict (seller_id) do update set
    store_id = excluded.store_id,
    business_name = excluded.business_name,
    status = 'active',
    activated_at = coalesce(
      public.ihiz_business_accounts.activated_at,
      timezone('utc', now())
    ),
    updated_at = timezone('utc', now())
  returning * into v_row;

  return jsonb_build_object(
    'ok', true,
    'store_id', v_row.store_id,
    'status', v_row.status,
    'business_name', v_row.business_name
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.list_ihiz_approved_couriers_directory()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return '[]'::jsonb;
  end if;
  if not (
    public.ihiz_actor_is_admin(v_uid)
    or exists (
      select 1
      from public.ihiz_business_accounts a
      where a.seller_id = v_uid
        and a.status in ('pending', 'active')
    )
  ) then
    return '[]'::jsonb;
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'user_id', app.user_id,
          'full_name', app.full_name,
          'city', app.city,
          'district', app.district
        )
        order by app.full_name
      )
      from public.ihiz_courier_applications app
      where lower(coalesce(app.status, '')) = 'approved'
    ),
    '[]'::jsonb
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.lookup_store_by_business_serial(p_serial text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := public.ihiz_normalize_business_serial(p_serial);
  v_hash text;
  v_addr inet := inet_client_addr();
  v_recent int := 0;
  v_store_id uuid;
  v_name text;
  v_city text;
  v_district text;
begin
  if v_code is null or v_code = '' or v_code !~ '^ISL-[A-Z0-9]{6}$' then
    return jsonb_build_object('found', false, 'error', 'not_found');
  end if;

  v_hash := encode(digest(v_code, 'sha256'), 'hex');
  insert into public.ihiz_business_serial_lookup_log (serial_hash, client_addr)
  values (v_hash, v_addr);

  select count(*)::int
  into v_recent
  from public.ihiz_business_serial_lookup_log
  where created_at > timezone('utc', now()) - interval '10 minutes'
    and (
      (v_addr is not null and client_addr = v_addr)
      or (v_addr is null and client_addr is null and serial_hash = v_hash)
    );

  if v_recent > 30 then
    return jsonb_build_object('found', false, 'error', 'rate_limited');
  end if;

  select serials.store_id, s.business_name, s.city, s.district
  into v_store_id, v_name, v_city, v_district
  from public.store_business_serials serials
  join public.stores s on s.seller_id = serials.store_id
  where serials.business_serial_no = v_code
  limit 1;

  if not found then
    return jsonb_build_object('found', false, 'error', 'not_found');
  end if;

  return jsonb_build_object(
    'found', true,
    'business_name', v_name,
    'city', v_city,
    'district', v_district
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.moderate_vehicle_listing(p_listing_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.vehicle_listings%rowtype;
  v_action text := lower(trim(coalesce(p_action, '')));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_payload jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  if not public.vehicle_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  select * into v_listing from public.vehicle_listings where id = p_listing_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if v_action = 'approve' then
    perform set_config('ibul.vehicle_moderation', '1', true);
    v_payload := coalesce(v_listing.ai_payload, '{}'::jsonb) - 'rejection_reason';
    v_payload := v_payload || jsonb_build_object(
      'moderation', jsonb_build_object(
        'status', 'approved',
        'reviewed_at', timezone('utc', now()),
        'reviewed_by', auth.uid()
      )
    );
    update public.vehicle_listings
    set
      status = 'active',
      published_at = timezone('utc', now()),
      ai_payload = v_payload
    where id = p_listing_id;
    return jsonb_build_object('ok', true, 'status', 'active');
  end if;

  if v_action = 'reject' then
    if v_reason is null then
      return jsonb_build_object('ok', false, 'error', 'reason_required');
    end if;
    update public.vehicle_listings
    set
      status = 'draft',
      published_at = null,
      ai_payload = coalesce(ai_payload, '{}'::jsonb) || jsonb_build_object(
        'moderation', jsonb_build_object(
          'status', 'rejected',
          'reason', v_reason,
          'reviewed_at', timezone('utc', now()),
          'reviewed_by', auth.uid()
        ),
        'rejection_reason', v_reason
      )
    where id = p_listing_id;
    return jsonb_build_object('ok', true, 'status', 'draft');
  end if;

  return jsonb_build_object('ok', false, 'error', 'invalid_action');
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_users_privileged_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allow boolean := false;
begin
  v_allow :=
    public.session_is_service_role()
    or current_setting('ibul.allow_privileged_user_update', true) = 'on';

  if tg_op = 'INSERT' then
    if v_allow then
      return new;
    end if;
    if public.is_admin_user(auth.uid())
       and auth.uid() is distinct from new.id then
      return new;
    end if;
    if new.role is null or btrim(new.role) = '' then
      new.role := 'user';
    end if;
    if public.is_admin_role(new.role)
       or lower(new.role) not in ('user', 'seller', 'customer', 'buyer') then
      new.role := 'user';
    end if;
    new.is_seller_approved := false;
    return new;
  end if;

  if v_allow then
    return new;
  end if;

  -- Admins may change another user's authorization columns via client or RPC.
  -- They may not self-promote; own-row privileged columns stay frozen.
  if public.is_admin_user(auth.uid())
     and auth.uid() is distinct from old.id then
    return new;
  end if;

  new.role := old.role;
  new.is_seller_approved := old.is_seller_approved;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_store_contract(p_contract_type text, p_title text, p_body_text text DEFAULT NULL::text, p_pdf_path text DEFAULT NULL::text, p_pdf_bucket text DEFAULT 'store-contracts'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_contract public.store_contracts%rowtype;
  v_version int;
  v_id uuid;
  v_hash text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  if p_contract_type not in ('product_sale', 'vehicle_rental') then
    return jsonb_build_object('ok', false, 'error', 'invalid_type');
  end if;
  if nullif(btrim(coalesce(p_title, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'title_required');
  end if;
  if nullif(btrim(coalesce(p_body_text, '')), '') is null
     and nullif(btrim(coalesce(p_pdf_path, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'content_required');
  end if;

  insert into public.store_contracts (seller_id, contract_type, title, is_active)
  values (v_uid, p_contract_type, btrim(p_title), true)
  on conflict (seller_id, contract_type) do update
    set title = excluded.title,
        is_active = true,
        updated_at = timezone('utc', now())
  returning * into v_contract;

  select coalesce(max(version), 0) + 1 into v_version
  from public.store_contract_versions
  where contract_id = v_contract.id;

  v_hash := encode(
    digest(convert_to(coalesce(p_body_text, '') || '|' || coalesce(p_pdf_path, ''), 'utf8'), 'sha256'),
    'hex'
  );

  insert into public.store_contract_versions (
    contract_id, version, body_text, pdf_bucket, pdf_path, content_sha256, created_by
  ) values (
    v_contract.id, v_version, nullif(btrim(coalesce(p_body_text, '')), ''),
    case when p_pdf_path is null then null else p_pdf_bucket end,
    nullif(btrim(coalesce(p_pdf_path, '')), ''),
    v_hash, v_uid
  ) returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'contract_id', v_contract.id,
    'version_id', v_id,
    'version', v_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.quote_vehicle_delivery_fee(p_listing_id uuid, p_mode text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_airport boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.vehicle_listings%rowtype;
  v_store public.stores%rowtype;
  v_settings public.vehicle_rental_settings%rowtype;
  v_km numeric;
  v_fee numeric := 0;
  v_label text := 'gallery';
  v_has_zone boolean := false;
begin
  select * into v_listing from public.vehicle_listings where id = p_listing_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'listing_not_found');
  end if;
  select * into v_store from public.stores where seller_id = v_listing.seller_id;
  select * into v_settings from public.vehicle_rental_settings where listing_id = p_listing_id;

  if p_mode = 'gallery_pickup' then
    return jsonb_build_object('ok', true, 'fee', 0, 'km', 0, 'label', 'gallery_pickup');
  end if;

  if p_mode = 'home_delivery' and (v_settings.home_delivery is distinct from true) then
    return jsonb_build_object('ok', false, 'error', 'home_delivery_disabled');
  end if;
  if p_mode = 'map_point' and (v_settings.map_point_delivery is distinct from true) then
    return jsonb_build_object('ok', false, 'error', 'map_point_disabled');
  end if;
  if p_lat is null or p_lng is null then
    return jsonb_build_object('ok', false, 'error', 'location_required');
  end if;
  if v_store.store_lat is null or v_store.store_lng is null then
    return jsonb_build_object('ok', false, 'error', 'gallery_location_missing');
  end if;

  v_km := 6371 * acos(
    least(1::numeric, greatest(-1::numeric,
      cos(radians(v_store.store_lat)) * cos(radians(p_lat)) *
      cos(radians(p_lng) - radians(v_store.store_lng)) +
      sin(radians(v_store.store_lat)) * sin(radians(p_lat))
    ))
  );

  if p_airport then
    select fee, label into v_fee, v_label
    from public.vehicle_delivery_zones
    where seller_id = v_listing.seller_id and is_airport
    order by fee asc
    limit 1;
    if v_fee is null then
      return jsonb_build_object('ok', false, 'error', 'airport_zone_missing', 'km', round(v_km, 2));
    end if;
  else
    select exists (
      select 1
      from public.vehicle_delivery_zones
      where seller_id = v_listing.seller_id and not is_airport
    ) into v_has_zone;
    if not v_has_zone then
      return jsonb_build_object('ok', false, 'error', 'delivery_zone_missing', 'km', round(v_km, 2));
    end if;
    select fee, label into v_fee, v_label
    from public.vehicle_delivery_zones
    where seller_id = v_listing.seller_id
      and not is_airport
      and v_km >= min_km and v_km <= max_km
    order by min_km asc
    limit 1;
    if v_fee is null then
      return jsonb_build_object(
        'ok', false,
        'error', 'out_of_zone',
        'km', round(v_km, 2)
      );
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'fee', v_fee,
    'km', round(v_km, 2),
    'label', v_label
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_waiter_request_items(p_seller_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  out jsonb := '[]'::jsonb;
  el jsonb;
  typ text;
  qty int;
  unit_p numeric;
  line_total numeric;
  children jsonb;
  child_rec record;
  child_unit numeric;
  child_qty int;
  child_lt numeric;
  acc_unit numeric;
  nm text;
  pid text;
  mixed_name text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return '[]'::jsonb;
  end if;

  for el in select value from jsonb_array_elements(p_items)
  loop
    typ := lower(coalesce(el.value ->> 'type', ''));
    if typ = 'waiter_call' then
      out := out || jsonb_build_array(el.value);
      continue;
    end if;

    if lower(coalesce(el.value ->> 'item_type', '')) = 'mixed_service' then
      mixed_name := coalesce(
        nullif(trim(el.value ->> 'item_name'), ''),
        nullif(trim(el.value ->> 'name'), ''),
        'Servis'
      );
      qty := greatest(coalesce((el.value ->> 'quantity')::int, 1), 1);
      children := coalesce(el.value -> 'child_items', '[]'::jsonb);
      acc_unit := 0;

      if jsonb_typeof(children) = 'array' then
        for child_rec in select jsonb_array_elements(children) as j
        loop
          child_qty := greatest(coalesce((child_rec.j ->> 'quantity')::int, 1), 1);
          pid := coalesce(
            nullif(trim(child_rec.j ->> 'product_id'), ''),
            nullif(trim(child_rec.j ->> 'productId'), '')
          );
          if pid is null or pid = '' then
            child_unit := coalesce(
              (child_rec.j ->> 'unit_price')::numeric,
              (child_rec.j ->> 'unit_price_snapshot')::numeric,
              0
            );
          else
            child_unit := public._waiter_req_simple_unit_price(
              p_seller_id,
              jsonb_build_object(
                'productId', pid,
                'selectedSizeName', child_rec.j ->> 'selected_size_name',
                'selectedWeightGrams', child_rec.j ->> 'selected_weight_grams',
                'selectedServiceAmount', child_rec.j ->> 'selected_service_amount'
              )
            );
          end if;
          child_lt := child_unit * child_qty::numeric;
          acc_unit := acc_unit + child_lt;
        end loop;
      end if;

      line_total := acc_unit * qty::numeric;
      out := out || jsonb_build_array(
        el.value
          || jsonb_build_object(
            'price', case when qty > 0 then acc_unit else 0 end,
            'unit_price_snapshot', acc_unit,
            'unitPriceSnapshot', acc_unit,
            'calculatedLineTotal', line_total,
            'line_total', line_total,
            'total_price', line_total,
            'server_priced', true
          )
      );
      continue;
    end if;

    qty := greatest(coalesce((el.value ->> 'quantity')::int, 1), 1);
    nm := coalesce(
      nullif(trim(el.value ->> 'name'), ''),
      nullif(trim(el.value ->> 'product_name'), ''),
      'Ürün'
    );
    unit_p := public._waiter_req_simple_unit_price(p_seller_id, el.value);
    line_total := unit_p * qty::numeric;
    out := out || jsonb_build_array(
      el.value
        || jsonb_build_object(
          'name', nm,
          'price', unit_p,
          'unit_price_snapshot', unit_p,
          'unitPriceSnapshot', unit_p,
          'calculatedLineTotal', line_total,
          'line_total', line_total,
          'total_price', line_total,
          'server_priced', true
        )
    );
  end loop;

  return out;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_waiter_order_request(p_request_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_seller uuid;
begin
  if auth.uid() is null then
    raise exception 'Yetkisiz istek.' using errcode = '42501';
  end if;

  select seller_id into v_seller
  from public.waiter_order_requests
  where id = p_request_id
  for update;

  if v_seller is null then
    raise exception 'İstek bulunamadı.' using errcode = '22023';
  end if;

  if not public.user_can_access_restaurant(v_seller) then
    raise exception 'Bu işletme için yetkiniz yok.' using errcode = '42501';
  end if;

  update public.waiter_order_requests
  set
    status = 'rejected',
    resolved_by = auth.uid(),
    resolved_at = now(),
    rejection_reason = nullif(trim(coalesce(p_reason, '')), '')
  where id = p_request_id
    and status = 'pending_waiter_approval';

  if not found then
    raise exception 'İstek reddedilemedi (durum uygun değil).' using errcode = '22023';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_admin_effective_role(target_user_id uuid DEFAULT auth.uid())
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  account_role text;
  permission_role text;
begin
  if target_user_id is null then
    return null;
  end if;

  if to_regclass('public.users') is not null then
    select lower(trim(u.role))
    into account_role
    from public.users u
    where u.id = target_user_id
    limit 1;
  end if;

  permission_role := null;
  if to_regclass('public.admin_user_permissions') is not null then
    select lower(trim(nullif(trim(a.role_key), '')))
    into permission_role
    from public.admin_user_permissions a
    where a.user_id = target_user_id and a.is_active = true
    limit 1;
  end if;

  if permission_role is not null and public.is_admin_role(permission_role) then
    return permission_role;
  end if;

  if account_role is not null and public.is_admin_role(account_role) then
    return account_role;
  end if;

  return coalesce(permission_role, account_role);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_vehicle_appointment(p_appointment_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_a public.vehicle_appointments%rowtype;
  v_status text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_a from public.vehicle_appointments where id = p_appointment_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if v_a.seller_id <> v_uid and v_a.customer_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if p_action = 'cancel' then
    v_status := 'cancelled';
  elsif v_a.seller_id = v_uid and p_action in ('confirm', 'reject', 'complete') then
    v_status := case p_action
      when 'confirm' then 'confirmed'
      when 'reject' then 'rejected'
      else 'completed'
    end;
  else
    return jsonb_build_object('ok', false, 'error', 'invalid_action');
  end if;

  update public.vehicle_appointments set status = v_status where id = p_appointment_id;
  return jsonb_build_object('ok', true, 'status', v_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_vehicle_quote(p_quote_id uuid, p_action text, p_counter_amount numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_q public.vehicle_quotes%rowtype;
  v_status text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_q from public.vehicle_quotes where id = p_quote_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if v_q.seller_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_q.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'invalid_state');
  end if;
  if p_action not in ('accept', 'reject', 'counter') then
    return jsonb_build_object('ok', false, 'error', 'invalid_action');
  end if;
  if p_action = 'counter' and (p_counter_amount is null or p_counter_amount <= 0) then
    return jsonb_build_object('ok', false, 'error', 'counter_amount_required');
  end if;

  v_status := case p_action
    when 'accept' then 'accepted'
    when 'reject' then 'rejected'
    else 'countered'
  end;

  update public.vehicle_quotes
  set status = v_status,
      counter_amount = case when p_action = 'counter' then p_counter_amount else counter_amount end,
      note = coalesce(p_note, note)
  where id = p_quote_id;

  insert into public.vehicle_quote_events (quote_id, actor_id, action, amount, note)
  values (p_quote_id, v_uid, p_action, coalesce(p_counter_amount, v_q.amount), p_note);

  if p_action = 'accept' then
    insert into public.vehicle_analytics_events (listing_id, seller_id, event_type, actor_id)
    values (v_q.listing_id, v_q.seller_id, 'quote', v_uid);
  end if;

  return jsonb_build_object('ok', true, 'status', v_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_vehicle_rental_reservation(p_reservation_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res public.vehicle_reservations%rowtype;
  v_next text;
  v_now timestamptz := timezone('utc', now());
  v_due timestamptz;
  v_title text;
  v_due_clock text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  if p_action not in ('approve', 'reject', 'seller_cancel') then
    return jsonb_build_object('ok', false, 'error', 'invalid_action');
  end if;
  select * into v_res from public.vehicle_reservations where id = p_reservation_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if v_res.seller_id <> v_uid and not public.vehicle_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  v_title := public.vehicle_rental_listing_title(v_res.listing_id);

  if p_action = 'approve' then
    if v_res.status <> 'pending_seller_review' then
      return jsonb_build_object('ok', false, 'error', 'invalid_state');
    end if;
    if public.vehicle_rental_window_blocked(
      v_res.listing_id, v_res.pickup_at, v_res.return_at, v_res.id
    ) then
      return jsonb_build_object('ok', false, 'error', 'not_available');
    end if;
    v_next := 'pending_payment';
    v_due := v_now + interval '3 hours';
    v_due_clock := to_char(v_due at time zone 'Europe/Istanbul', 'HH24:MI');
    update public.vehicle_reservations
    set status = v_next,
        confirmed_at = v_now,
        approved_at = v_now,
        payment_due_at = v_due
    where id = p_reservation_id;
    perform public.vehicle_rental_notify(
      v_res.customer_id,
      'Kiralama talebiniz onaylandı',
      v_title || ' kiralama talebiniz onaylandı. Rezervasyonu kesinleştirmek için 3 saat içinde ödeme yapın. Ödeme son zamanı: ' || v_due_clock,
      'vehicle_rental_seller_approved',
      jsonb_build_object(
        'reservation_id', p_reservation_id,
        'rental_code', v_res.rental_code,
        'listing_title', v_title,
        'payment_due_at', v_due,
        'open_tab', 'rental'
      )
    );
  elsif p_action = 'reject' then
    if nullif(btrim(coalesce(p_reason, '')), '') is null then
      return jsonb_build_object('ok', false, 'error', 'reason_required');
    end if;
    if v_res.status not in ('pending_seller_review', 'pending_payment', 'pending_docs') then
      return jsonb_build_object('ok', false, 'error', 'invalid_state');
    end if;
    if v_res.payment_status in ('paid', 'authorized') then
      v_next := 'refund_pending';
      insert into public.vehicle_rental_refunds (booking_id, amount, reason, status)
      values (p_reservation_id, v_res.total, p_reason, 'refund_pending');
      update public.vehicle_reservations
      set status = v_next,
          payment_status = 'refund_pending',
          reject_reason = p_reason,
          cancelled_at = v_now,
          refund_amount = v_res.total,
          refund_reason = p_reason
      where id = p_reservation_id;
    else
      v_next := 'rejected';
      update public.vehicle_reservations
      set status = v_next,
          reject_reason = p_reason,
          cancelled_at = v_now
      where id = p_reservation_id;
    end if;
    perform public.vehicle_rental_notify(
      v_res.customer_id,
      'Kiralama talebiniz reddedildi',
      case when v_next = 'refund_pending' then 'İade başlatıldı.'
           else 'Ödeme alınmadığı için iade gerekmedi.' end,
      'vehicle_rental_seller_rejected',
      jsonb_build_object(
        'reservation_id', p_reservation_id,
        'rental_code', v_res.rental_code
      )
    );
  else
    if nullif(btrim(coalesce(p_reason, '')), '') is null then
      return jsonb_build_object('ok', false, 'error', 'reason_required');
    end if;
    if v_res.status not in ('pending_payment', 'confirmed', 'reserved') then
      return jsonb_build_object('ok', false, 'error', 'invalid_state');
    end if;
    if v_res.payment_status in ('paid', 'authorized') then
      insert into public.vehicle_rental_refunds (booking_id, amount, reason, status)
      values (p_reservation_id, v_res.total, p_reason, 'refund_pending');
      update public.vehicle_reservations
      set status = 'seller_cancelled',
          payment_status = 'refund_pending',
          cancel_reason = p_reason,
          cancel_actor = 'seller',
          cancelled_at = v_now,
          refund_amount = v_res.total,
          refund_reason = p_reason
      where id = p_reservation_id;
      v_next := 'seller_cancelled';
    else
      v_next := 'seller_cancelled';
      update public.vehicle_reservations
      set status = v_next,
          cancel_reason = p_reason,
          cancel_actor = 'seller',
          cancelled_at = v_now
      where id = p_reservation_id;
    end if;
    if v_res.status in ('reserved', 'confirmed') then
      update public.vehicle_listings
      set status = 'active'
      where id = v_res.listing_id and status = 'reserved';
    end if;
    perform public.vehicle_rental_notify(
      v_res.customer_id,
      'Rezervasyon satıcı tarafından iptal edildi',
      'Satıcı kaynaklı iptalde müşteri cezalandırılmaz. İade varsa başlatılır.',
      'vehicle_rental_seller_cancelled',
      jsonb_build_object(
        'reservation_id', p_reservation_id,
        'rental_code', v_res.rental_code
      )
    );
  end if;

  perform public.vehicle_rental_log_event(p_reservation_id, v_uid, p_action, v_res.status, v_next);
  return jsonb_build_object(
    'ok', true,
    'status', v_next,
    'reservation_id', p_reservation_id,
    'payment_due_at', v_due
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_own_admin_role()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_role text;
begin
  if v_uid is null then
    return null;
  end if;

  select u.role into v_role
  from public.users u
  where u.id = v_uid;

  if public.is_admin_role(v_role) then
    return v_role;
  end if;

  v_role := null;
  if to_regclass('public.admin_user_permissions') is not null then
    execute
      'select coalesce(nullif(btrim(p.role_key), ''''), ''admin'')
         from public.admin_user_permissions p
        where p.user_id = $1
          and coalesce(p.is_active, true) = true
        limit 1'
      into v_role
      using v_uid;
  end if;

  if public.is_admin_role(v_role) then
    perform set_config('ibul.allow_privileged_user_update', 'on', true);
    update public.users
    set role = v_role,
        updated_at = timezone('utc', now())
    where id = v_uid;
    return v_role;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reward_wheel_admin_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today timestamptz := date_trunc('day', timezone('Europe/Istanbul', timezone('utc', now())))
    at time zone 'Europe/Istanbul';
  v_config uuid;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'not authorized';
  end if;

  select id into v_config
  from public.reward_wheel_configs
  order by updated_at desc
  limit 1;

  return jsonb_build_object(
    'active_rewards', (
      select count(*) from public.reward_wheel_items
      where config_id = v_config and coalesce(is_active, true)
    ),
    'pending_seller_offers', (
      select count(*) from public.coupon_campaigns
      where wheel_requested = true
        and approval_status = 'pending_review'
    ),
    'today_spins', (
      select count(*) from public.reward_wheel_spins
      where created_at >= v_today
    ),
    'today_wins', (
      select count(*) from public.reward_wheel_spins
      where created_at >= v_today and is_win = true
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reward_wheel_compose_for_user(p_user uuid, p_config reward_wheel_configs)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
  v_has_signals boolean := false;
  v_items jsonb := '[]'::jsonb;
  v_dropped int := 0;
  v_row record;
  v_no_prize jsonb;
  v_cat_tokens text[] := '{}';
  v_store_ids uuid[] := '{}';
  v_product_ids text[] := '{}';
begin
  if p_user is not null and to_regclass('public.orders') is not null then
    begin
      select coalesce(array_agg(distinct o.seller_id), '{}')
      into v_store_ids
      from public.orders o
      where o.user_id = p_user
        and o.seller_id is not null;

      if to_regclass('public.order_items') is not null then
        select coalesce(array_agg(distinct oi.product_id::text), '{}')
        into v_product_ids
        from public.orders o
        join public.order_items oi on oi.order_id = o.id
        where o.user_id = p_user
          and oi.product_id is not null;

        select coalesce(array_agg(distinct lower(btrim(p.main_category))), '{}')
        into v_cat_tokens
        from public.orders o
        join public.order_items oi on oi.order_id = o.id
        join public.products p on p.id = oi.product_id
        where o.user_id = p_user
          and coalesce(p.main_category, '') <> '';
      end if;
    exception when others then
      v_cat_tokens := '{}';
      v_store_ids := '{}';
      v_product_ids := '{}';
    end;
  end if;

  v_has_signals :=
    coalesce(array_length(v_cat_tokens, 1), 0) > 0
    or coalesce(array_length(v_store_ids, 1), 0) > 0
    or coalesce(array_length(v_product_ids, 1), 0) > 0;

  for v_row in
    select
      i.*,
      c as campaign,
      (
        case
          when i.is_no_prize then 1
          when c.id is null then 0
          else
            (case when exists (
                  select 1 from unnest(v_cat_tokens) s(token)
                  where length(s.token) >= 3
                    and position(s.token in lower(coalesce(i.label, '') || ' ' || coalesce(c.name, ''))) > 0
                ) then 3 else 0 end)
            + (case when c.store_id = any(v_store_ids) or c.seller_id = any(v_store_ids)
               then 2 else 0 end)
            + (
              select count(*) from public.coupon_campaign_products cp
              where cp.campaign_id = c.id
                and cp.product_id = any(v_product_ids)
            ) * 2
        end
      ) as relevance
    from public.reward_wheel_items i
    left join public.coupon_campaigns c on c.id = i.campaign_id
    where i.config_id = p_config.id
      and coalesce(i.is_active, true)
    order by i.sort_order, i.created_at
  loop
    if v_row.is_no_prize then
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'id', v_row.id,
        'campaign_id', v_row.campaign_id,
        'label', v_row.label,
        'is_no_prize', true,
        'is_active', true,
        'probability_bps', v_row.probability_bps,
        'sort_order', v_row.sort_order,
        'color_hex', v_row.color_hex,
        'relevance', 1
      ));
      continue;
    end if;

    if v_row.campaign is null
       or not public.reward_wheel_coupon_winnable(v_row.campaign, v_now) then
      v_dropped := v_dropped + v_row.probability_bps;
      continue;
    end if;

    if coalesce(p_config.use_global_pool, true) or not v_has_signals or v_row.relevance > 0 then
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'id', v_row.id,
        'campaign_id', v_row.campaign_id,
        'label', v_row.label,
        'is_no_prize', false,
        'is_active', true,
        'probability_bps', v_row.probability_bps,
        'sort_order', v_row.sort_order,
        'color_hex', v_row.color_hex,
        'relevance', v_row.relevance
      ));
    else
      v_dropped := v_dropped + v_row.probability_bps;
    end if;
  end loop;

  if v_dropped > 0 then
    select value
      into v_no_prize
    from jsonb_array_elements(v_items) as t(value)
    where (value->>'is_no_prize')::boolean
    limit 1;

    if v_no_prize is not null then
      v_items := (
        select jsonb_agg(
          case
            when (value->>'is_no_prize')::boolean then
              jsonb_set(
                value,
                '{probability_bps}',
                to_jsonb(least(10000, (value->>'probability_bps')::int + v_dropped))
              )
            else value
          end
        )
        from jsonb_array_elements(v_items) as t(value)
      );
    end if;
  end if;

  if v_has_signals
     and not coalesce(p_config.use_global_pool, true)
     and not exists (
       select 1 from jsonb_array_elements(v_items) t(value)
       where coalesce((value->>'is_no_prize')::boolean, false) = false
     ) then
    return public.reward_wheel_compose_for_user(null, p_config);
  end if;

  return coalesce(v_items, '[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.reward_wheel_save_config(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_total int := 0;
  v_item jsonb;
  v_campaign uuid;
  v_active_total int := 0;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'not authorized';
  end if;

  if jsonb_typeof(p_payload->'items') is distinct from 'array' then
    raise exception 'wheel items required';
  end if;

  select coalesce(sum((value->>'probability_bps')::int), 0)
  into v_total
  from jsonb_array_elements(p_payload->'items')
  where coalesce((value->>'is_active')::boolean, true);

  if v_total <> 10000 then
    raise exception 'probability total must be 100 percent'
      using errcode = 'P0001',
            hint = v_total::text;
  end if;

  v_id := nullif(p_payload->>'id', '')::uuid;

  if v_id is null then
    insert into public.reward_wheel_configs (
      is_active, daily_free_spins, cooldown_hours, starts_at, ends_at,
      created_by, use_global_pool, per_user_daily_limit
    ) values (
      coalesce((p_payload->>'is_active')::boolean, false),
      coalesce((p_payload->>'daily_free_spins')::int, 1),
      coalesce((p_payload->>'cooldown_hours')::numeric, 24),
      nullif(p_payload->>'starts_at', '')::timestamptz,
      nullif(p_payload->>'ends_at', '')::timestamptz,
      auth.uid(),
      coalesce((p_payload->>'use_global_pool')::boolean, true),
      coalesce((p_payload->>'per_user_daily_limit')::int, 1)
    )
    returning id into v_id;
  else
    update public.reward_wheel_configs
    set is_active = coalesce((p_payload->>'is_active')::boolean, is_active),
        daily_free_spins = coalesce((p_payload->>'daily_free_spins')::int, daily_free_spins),
        cooldown_hours = coalesce((p_payload->>'cooldown_hours')::numeric, cooldown_hours),
        starts_at = nullif(p_payload->>'starts_at', '')::timestamptz,
        ends_at = nullif(p_payload->>'ends_at', '')::timestamptz,
        use_global_pool = coalesce((p_payload->>'use_global_pool')::boolean, use_global_pool),
        per_user_daily_limit = coalesce(
          (p_payload->>'per_user_daily_limit')::int,
          per_user_daily_limit
        )
    where id = v_id;
    if not found then
      raise exception 'wheel config not found';
    end if;
  end if;

  delete from public.reward_wheel_items where config_id = v_id;

  for v_item in select value from jsonb_array_elements(p_payload->'items')
  loop
    v_campaign := nullif(v_item->>'campaign_id', '')::uuid;
    if v_campaign is not null then
      if not exists (
        select 1 from public.coupon_campaigns c
        where c.id = v_campaign
          and c.approval_status = 'approved'
      ) then
        raise exception 'wheel item must reference an approved coupon';
      end if;
      update public.coupon_campaigns
      set wheel_enabled = true
      where id = v_campaign;
    end if;

    insert into public.reward_wheel_items (
      config_id, campaign_id, label, is_no_prize, probability_bps, sort_order,
      color_hex, is_active
    ) values (
      v_id,
      v_campaign,
      coalesce(nullif(v_item->>'label', ''), 'Ödül'),
      coalesce((v_item->>'is_no_prize')::boolean, v_campaign is null),
      coalesce((v_item->>'probability_bps')::int, 0),
      coalesce((v_item->>'sort_order')::int, 0),
      nullif(v_item->>'color_hex', ''),
      coalesce((v_item->>'is_active')::boolean, true)
    );
    if coalesce((v_item->>'is_active')::boolean, true) then
      v_active_total := v_active_total + 1;
    end if;
  end loop;

  update public.coupon_campaigns c
  set wheel_enabled = exists (
    select 1 from public.reward_wheel_items i
    where i.config_id = v_id and i.campaign_id = c.id
  )
  where c.wheel_enabled = true
     or exists (
       select 1 from public.reward_wheel_items i
       where i.config_id = v_id and i.campaign_id = c.id
     );

  return jsonb_build_object(
    'ok', true,
    'id', v_id,
    'probability_bps', v_total,
    'active_item_count', v_active_total
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reward_wheel_user_eligibility(p_user uuid, p_config reward_wheel_configs, p_now timestamp with time zone DEFAULT timezone('utc'::text, now()))
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_daily_limit int;
  v_spin_count int := 0;
  v_last timestamptz;
  v_day_start timestamptz;
  v_cooldown_until timestamptz;
  v_next timestamptz;
  v_can boolean := true;
  v_reason text := 'ok';
begin
  if p_user is null then
    return jsonb_build_object(
      'can_spin', false,
      'reason', 'not_authenticated',
      'daily_used', 0,
      'daily_limit', 0,
      'last_spin_at', null,
      'next_spin_at', null
    );
  end if;

  if p_config.id is null or coalesce(p_config.is_active, false) is not true then
    return jsonb_build_object(
      'can_spin', false,
      'reason', 'inactive',
      'daily_used', 0,
      'daily_limit', 0,
      'last_spin_at', null,
      'next_spin_at', null
    );
  end if;

  if p_config.starts_at is not null and p_now < p_config.starts_at then
    return jsonb_build_object(
      'can_spin', false,
      'reason', 'not_started',
      'daily_used', 0,
      'daily_limit', greatest(
        coalesce(p_config.daily_free_spins, 0),
        coalesce(p_config.per_user_daily_limit, 0)
      ),
      'last_spin_at', null,
      'next_spin_at', p_config.starts_at
    );
  end if;

  if p_config.ends_at is not null and p_now > p_config.ends_at then
    return jsonb_build_object(
      'can_spin', false,
      'reason', 'ended',
      'daily_used', 0,
      'daily_limit', greatest(
        coalesce(p_config.daily_free_spins, 0),
        coalesce(p_config.per_user_daily_limit, 0)
      ),
      'last_spin_at', null,
      'next_spin_at', null
    );
  end if;

  v_daily_limit := greatest(
    coalesce(p_config.daily_free_spins, 0),
    coalesce(p_config.per_user_daily_limit, 0)
  );
  v_day_start := date_trunc('day', timezone('Europe/Istanbul', p_now))
    at time zone 'Europe/Istanbul';

  select count(*)
  into v_spin_count
  from public.reward_wheel_spins
  where user_id = p_user
    and created_at >= v_day_start;

  select max(created_at)
  into v_last
  from public.reward_wheel_spins
  where user_id = p_user;

  if v_daily_limit > 0 and v_spin_count >= v_daily_limit then
    v_can := false;
    v_reason := 'daily_limit';
    v_next := v_day_start + interval '1 day';
  end if;

  if p_config.cooldown_hours > 0 and v_last is not null then
    v_cooldown_until := v_last + (p_config.cooldown_hours || ' hours')::interval;
    if v_cooldown_until > p_now then
      v_can := false;
      if v_next is null or v_cooldown_until > v_next then
        v_next := v_cooldown_until;
        v_reason := 'cooldown';
      end if;
    end if;
  end if;

  if v_can then
    v_reason := 'ok';
    v_next := null;
  end if;

  return jsonb_build_object(
    'can_spin', v_can,
    'reason', v_reason,
    'daily_used', v_spin_count,
    'daily_limit', v_daily_limit,
    'last_spin_at', v_last,
    'next_spin_at', v_next
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.seller_reset_password_with_recovery_code(p_identifier text, p_code text, p_new_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_ident text := lower(trim(both from coalesce(p_identifier, '')));
  v_phone text := public._store_recovery_normalize_phone(p_identifier);
  v_ident_hash text;
  v_attempts int;
  v_store_id uuid;
  v_hash text;
  v_code_id uuid;
begin
  if length(coalesce(p_new_password, '')) < 6 then
    raise exception 'password too short';
  end if;
  if length(coalesce(p_code, '')) < 8 then
    raise exception 'invalid code';
  end if;
  if v_ident = '' then
    raise exception 'identifier required';
  end if;

  v_ident_hash := encode(digest(v_ident, 'sha256'), 'hex');

  select count(*) into v_attempts
  from public.store_recovery_attempts a
  where a.identifier_hash = v_ident_hash
    and a.created_at > timezone('utc', now()) - interval '15 minutes'
    and a.success = false;
  if v_attempts >= 8 then
    raise exception 'too many attempts';
  end if;

  select s.seller_id
    into v_store_id
  from public.stores s
  left join public.users u on u.id = s.seller_id
  where lower(trim(both from coalesce(s.email, ''))) = v_ident
     or lower(trim(both from coalesce(u.email, ''))) = v_ident
     or public._store_recovery_normalize_phone(s.phone) = v_phone
     or public._store_recovery_normalize_phone(u.phone) = v_phone
  order by s.created_at desc
  limit 1;

  if v_store_id is null then
    insert into public.store_recovery_attempts (identifier_hash, success)
    values (v_ident_hash, false);
    raise exception 'invalid recovery';
  end if;

  v_hash := public._store_recovery_hash(v_store_id, p_code);

  select c.id into v_code_id
  from public.store_recovery_codes c
  where c.store_id = v_store_id
    and c.code_hash = v_hash
    and c.used_at is null
  limit 1;

  if v_code_id is null then
    insert into public.store_recovery_attempts (identifier_hash, success)
    values (v_ident_hash, false);
    raise exception 'invalid recovery';
  end if;

  update auth.users
  set encrypted_password = crypt(p_new_password, gen_salt('bf')),
      updated_at = timezone('utc', now())
  where id = v_store_id;

  if not found then
    raise exception 'auth user missing';
  end if;

  update public.store_recovery_codes
  set used_at = timezone('utc', now())
  where id = v_code_id;

  insert into public.store_recovery_attempts (identifier_hash, success)
  values (v_ident_hash, true);

  return jsonb_build_object('ok', true, 'store_id', v_store_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_store_contract_active(p_contract_type text, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  update public.store_contracts
  set is_active = p_active, updated_at = timezone('utc', now())
  where seller_id = v_uid and contract_type = p_contract_type;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.spin_reward_wheel(p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_existing public.reward_wheel_spins%rowtype;
  v_config public.reward_wheel_configs%rowtype;
  v_item public.reward_wheel_items%rowtype;
  v_campaign public.coupon_campaigns%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_roll int;
  v_cursor int := 0;
  v_spin_id uuid;
  v_user_coupon uuid;
  v_visible jsonb;
  v_choice jsonb;
  v_elig jsonb;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;
  if v_key = '' then
    raise exception 'idempotency key required';
  end if;

  select * into v_existing
  from public.reward_wheel_spins
  where user_id = v_user and idempotency_key = v_key;
  if found then
    return jsonb_build_object(
      'ok', true,
      'already_processed', true,
      'can_spin', false,
      'spin_id', v_existing.id,
      'is_win', v_existing.is_win,
      'item_id', v_existing.item_id,
      'campaign_id', v_existing.campaign_id,
      'user_coupon_id', v_existing.user_coupon_id
    );
  end if;

  select * into v_config
  from public.reward_wheel_configs
  where is_active = true
  order by updated_at desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'Hediye çarkı şu anda kapalı.');
  end if;

  v_elig := public.reward_wheel_user_eligibility(v_user, v_config, v_now);
  if coalesce((v_elig->>'can_spin')::boolean, false) is not true then
    return jsonb_build_object(
      'ok', false,
      'can_spin', false,
      'error', case v_elig->>'reason'
        when 'not_authenticated' then 'Giriş yapmalısınız.'
        when 'inactive' then 'Hediye çarkı şu anda kapalı.'
        when 'not_started' then 'Hediye çarkı henüz başlamadı.'
        when 'ended' then 'Hediye çarkı süresi doldu.'
        when 'daily_limit' then 'Bugünkü çevirme hakkınız doldu.'
        when 'cooldown' then 'Çevirme hakkınız henüz dolmadı.'
        else 'Çark çevrilemedi.'
      end
    );
  end if;

  v_visible := public.reward_wheel_compose_for_user(v_user, v_config);
  if v_visible is null or jsonb_array_length(v_visible) = 0 then
    return jsonb_build_object('ok', false, 'error', 'Çark ödülleri tanımlı değil.');
  end if;

  v_roll := floor(random() * 10000)::int;
  for v_choice in select value from jsonb_array_elements(v_visible)
  loop
    v_cursor := v_cursor + coalesce((v_choice->>'probability_bps')::int, 0);
    if v_roll < v_cursor then
      exit;
    end if;
  end loop;

  if v_choice is null then
    return jsonb_build_object('ok', false, 'error', 'Çark ödülleri tanımlı değil.');
  end if;

  select * into v_item
  from public.reward_wheel_items
  where id = nullif(v_choice->>'id', '')::uuid;

  if coalesce((v_choice->>'is_no_prize')::boolean, false) = false
     and v_item.campaign_id is not null then
    select * into v_campaign
    from public.coupon_campaigns
    where id = v_item.campaign_id
    for update;
    if not found or not public.reward_wheel_coupon_winnable(v_campaign, v_now) then
      v_item.is_no_prize := true;
      v_campaign := null;
    else
      insert into public.user_coupons (user_id, campaign_id, status, source)
      values (v_user, v_item.campaign_id, 'claimed', 'wheel')
      on conflict (user_id, campaign_id) where status in ('claimed', 'reserved')
      do nothing
      returning id into v_user_coupon;
      if v_user_coupon is null then
        select id into v_user_coupon
        from public.user_coupons
        where user_id = v_user
          and campaign_id = v_item.campaign_id
          and status in ('claimed', 'reserved', 'used')
        order by claimed_at desc
        limit 1;
      else
        update public.coupon_campaigns
        set claim_count = claim_count + 1,
            used_count = used_count + 1
        where id = v_item.campaign_id;
      end if;
    end if;
  end if;

  insert into public.reward_wheel_spins (
    config_id, user_id, item_id, campaign_id, user_coupon_id, is_win, idempotency_key
  ) values (
    v_config.id,
    v_user,
    v_item.id,
    case when v_user_coupon is not null then v_item.campaign_id else null end,
    v_user_coupon,
    v_user_coupon is not null,
    v_key
  )
  returning id into v_spin_id;

  if v_user_coupon is not null then
    update public.user_coupons
    set spin_id = v_spin_id
    where id = v_user_coupon;
  end if;

  v_elig := public.reward_wheel_user_eligibility(v_user, v_config, v_now);

  return jsonb_build_object(
    'ok', true,
    'already_processed', false,
    'can_spin', coalesce((v_elig->>'can_spin')::boolean, false),
    'spin_id', v_spin_id,
    'item_id', v_item.id,
    'label', coalesce(v_choice->>'label', v_item.label),
    'is_win', v_user_coupon is not null,
    'is_no_prize', v_user_coupon is null,
    'campaign_id', v_item.campaign_id,
    'user_coupon_id', v_user_coupon,
    'sort_order', v_item.sort_order
  );
exception
  when unique_violation then
    select * into v_existing
    from public.reward_wheel_spins
    where user_id = v_user and idempotency_key = v_key;
    return jsonb_build_object(
      'ok', true,
      'already_processed', true,
      'can_spin', false,
      'spin_id', v_existing.id,
      'is_win', v_existing.is_win,
      'item_id', v_existing.item_id,
      'campaign_id', v_existing.campaign_id,
      'user_coupon_id', v_existing.user_coupon_id
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_vehicle_listing_for_review(p_listing_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_listing public.vehicle_listings%rowtype;
  v_spec public.vehicle_specs%rowtype;
  v_media_count integer := 0;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_listing from public.vehicle_listings where id = p_listing_id for update;
  if not found or v_listing.seller_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_listing.status = 'pending_review' then
    return jsonb_build_object('ok', true, 'status', 'pending_review');
  end if;
  if v_listing.status = 'active' then
    return jsonb_build_object('ok', false, 'error', 'already_published', 'status', v_listing.status);
  end if;
  if v_listing.status not in ('draft', 'inactive') then
    return jsonb_build_object(
      'ok', false,
      'error', 'invalid_state',
      'status', v_listing.status
    );
  end if;
  select * into v_spec from public.vehicle_specs where listing_id = p_listing_id;
  if not found
     or nullif(trim(coalesce(v_spec.brand, '')), '') is null
     or nullif(trim(coalesce(v_spec.model, '')), '') is null
     or v_spec.year is null then
    return jsonb_build_object('ok', false, 'error', 'specs_required');
  end if;
  if v_listing.listing_type in ('sale', 'both') and coalesce(v_listing.sale_price, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'sale_price_required');
  end if;
  if v_listing.listing_type in ('rental', 'both')
     and not exists (select 1 from public.vehicle_rental_settings where listing_id = p_listing_id) then
    return jsonb_build_object('ok', false, 'error', 'rental_settings_required');
  end if;
  select count(*) into v_media_count
  from public.vehicle_media
  where listing_id = p_listing_id;
  if v_media_count < 1 and nullif(trim(coalesce(v_listing.cover_url, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'photos_required');
  end if;

  update public.vehicle_listings
  set
    status = 'pending_review',
    ai_payload = coalesce(ai_payload, '{}'::jsonb) || jsonb_build_object(
      'moderation', jsonb_build_object(
        'status', 'pending',
        'submitted_at', timezone('utc', now())
      )
    )
  where id = p_listing_id;

  return jsonb_build_object('ok', true, 'status', 'pending_review');
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_vehicle_rental_for_review(p_reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res public.vehicle_reservations%rowtype;
  v_settings public.vehicle_rental_settings%rowtype;
  v_docs int;
  v_next text;
  v_has_contract boolean := false;
  v_accepted boolean := false;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth_required');
  end if;
  select * into v_res from public.vehicle_reservations where id = p_reservation_id for update;
  if not found or v_res.customer_id <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_res.status in ('pending_seller_review', 'pending_payment') then
    return jsonb_build_object(
      'ok', true,
      'status', v_res.status,
      'reservation_id', p_reservation_id,
      'rental_code', v_res.rental_code,
      'idempotent', true
    );
  end if;
  if v_res.status <> 'pending_docs' then
    return jsonb_build_object('ok', false, 'error', 'invalid_state');
  end if;
  if v_res.terms_accepted_at is null then
    return jsonb_build_object('ok', false, 'error', 'terms_required');
  end if;
  if nullif(btrim(coalesce(v_res.customer_name, '')), '') is null
     or nullif(btrim(coalesce(v_res.customer_phone, '')), '') is null
     or nullif(btrim(coalesce(v_res.customer_email, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'validation_failed');
  end if;
  if not public.tr_national_id_valid(v_res.customer_national_id) then
    return jsonb_build_object('ok', false, 'error', 'invalid_national_id');
  end if;

  select exists (
    select 1 from public.store_contracts c
    where c.seller_id = v_res.seller_id
      and c.contract_type = 'vehicle_rental'
      and c.is_active
  ) into v_has_contract;
  if not v_has_contract then
    return jsonb_build_object('ok', false, 'error', 'contract_required');
  end if;
  select exists (
    select 1
    from public.store_contract_acceptances a
    join public.store_contract_versions v on v.id = a.contract_version_id
    join public.store_contracts c on c.id = v.contract_id
    where a.reservation_id = p_reservation_id
      and a.accepted_by = v_uid
      and c.seller_id = v_res.seller_id
      and c.contract_type = 'vehicle_rental'
      and c.is_active
  ) into v_accepted;
  if not v_accepted then
    return jsonb_build_object('ok', false, 'error', 'contract_required');
  end if;

  select count(*) into v_docs
  from (
    select d.doc_type
    from public.vehicle_kyc_documents d
    where d.reservation_id = p_reservation_id
      and d.status in ('submitted', 'verified')
      and d.doc_type in (
        'identity_front', 'identity_back',
        'driver_license_front', 'driver_license_back'
      )
    group by d.doc_type
  ) x;
  if v_docs < 4 then
    return jsonb_build_object('ok', false, 'error', 'documents_required');
  end if;
  select * into v_settings from public.vehicle_rental_settings where listing_id = v_res.listing_id;
  if coalesce(v_settings.instant_booking, false) and not coalesce(v_settings.requires_approval, true) then
    v_next := 'pending_payment';
  else
    v_next := 'pending_seller_review';
  end if;
  update public.vehicle_reservations set status = v_next where id = p_reservation_id;
  select rental_code into v_res.rental_code from public.vehicle_reservations where id = p_reservation_id;
  perform public.vehicle_rental_log_event(p_reservation_id, v_uid, 'submitted', 'pending_docs', v_next);
  perform public.vehicle_rental_notify(
    v_res.seller_id,
    'Kiralama talebi incelenebilir',
    'Belgeler yüklendi. Talebi onaylayabilir veya reddedebilirsiniz.',
    'vehicle_rental_ready_for_review'
  );
  perform public.vehicle_rental_notify(
    v_res.customer_id,
    'Kiralama talebiniz alındı',
    'Talebiniz satıcı incelemesine gönderildi.',
    'vehicle_rental_request_received'
  );
  return jsonb_build_object(
    'ok', true,
    'status', v_next,
    'reservation_id', p_reservation_id,
    'rental_code', v_res.rental_code
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_waiter_order_request(p_seller_id uuid, p_table_number integer, p_items jsonb, p_customer_notes text DEFAULT NULL::text, p_table_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Oturum açmanız gerekir.' using errcode = '42501';
  end if;
  if p_table_number is null or p_table_number <= 0 then
    raise exception 'Geçersiz masa numarası.' using errcode = '22023';
  end if;
  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then
    raise exception 'İstek kalemleri boş olamaz.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.stores s where s.seller_id = p_seller_id) then
    raise exception 'Mağaza bulunamadı.' using errcode = '22023';
  end if;

  insert into public.waiter_order_requests (
    seller_id,
    table_number,
    items_draft,
    customer_notes,
    table_payload,
    status,
    created_by
  ) values (
    p_seller_id,
    p_table_number,
    p_items,
    nullif(trim(coalesce(p_customer_notes, '')), ''),
    coalesce(p_table_payload, '{}'::jsonb),
    'pending_waiter_approval',
    v_uid
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_store_follower_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_store_id uuid := coalesce(new.store_id, old.store_id);
begin
  if v_store_id is null then
    return coalesce(new, old);
  end if;

  update public.stores
  set follower_count = (
    select count(*)::integer
    from public.store_followers sf
    where sf.store_id = v_store_id
  ),
  updated_at = now()
  where seller_id = v_store_id;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.toggle_store_notifications(p_store_id uuid, p_enabled boolean, p_fcm_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_enabled boolean;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if not exists (
    select 1 from public.store_followers
    where store_id = p_store_id and user_id = v_user_id
  ) then
    raise exception 'not_following';
  end if;

  if p_enabled then
    insert into public.store_notification_preferences (
      store_id, user_id, enabled, fcm_token, updated_at
    )
    values (
      p_store_id, v_user_id, true, nullif(trim(p_fcm_token), ''), now()
    )
    on conflict (store_id, user_id) do update
    set enabled = true,
        fcm_token = coalesce(nullif(trim(excluded.fcm_token), ''), store_notification_preferences.fcm_token),
        updated_at = now();
    v_enabled := true;
  else
    update public.store_notification_preferences
    set enabled = false, updated_at = now()
    where store_id = p_store_id and user_id = v_user_id;

    if not found then
      v_enabled := false;
    else
      v_enabled := false;
    end if;
  end if;

  return jsonb_build_object('enabled', v_enabled);
end;
$function$

CREATE OR REPLACE FUNCTION public.transfer_table_orders(p_seller_id uuid, p_from_table integer, p_to_table integer, p_transfer_type text DEFAULT 'full'::text, p_item_ids jsonb DEFAULT '[]'::jsonb, p_waiter_id uuid DEFAULT NULL::uuid, p_waiter_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_src_orders   jsonb := '[]'::jsonb;
  v_moved_items  jsonb := '[]'::jsonb;
  v_order        record;
  v_new_items    jsonb;
  v_dst_order    record;
  v_order_id_list jsonb := '[]'::jsonb;
begin
  if p_seller_id <> auth.uid() then
    raise exception 'Yetki hatası.' using errcode = '42501';
  end if;
  if p_from_table = p_to_table then
    raise exception 'Kaynak ve hedef masa aynı olamaz.';
  end if;

  -- Collect source orders
  for v_order in
    select * from public.table_orders
    where seller_id = p_seller_id and table_number = p_from_table
  loop
    v_order_id_list := v_order_id_list || to_jsonb(v_order.id::text);

    if p_transfer_type = 'full' then
      -- Move entire order to destination
      update public.table_orders
      set table_number = p_to_table,
          updated_at   = timezone('utc',now())
      where id = v_order.id;
      v_moved_items := v_moved_items || coalesce(v_order.items,'[]'::jsonb);
    else
      -- Partial: only move items whose 'id' is in p_item_ids
      select
        jsonb_agg(item) filter (where (item->>'id') = any(select jsonb_array_elements_text(p_item_ids))),
        jsonb_agg(item) filter (where (item->>'id') <> all(select jsonb_array_elements_text(p_item_ids)))
      into v_moved_items, v_new_items
      from jsonb_array_elements(coalesce(v_order.items,'[]'::jsonb)) item;

      if v_new_items is null or jsonb_array_length(v_new_items) = 0 then
        -- All items transferred → move entire order row
        update public.table_orders
        set table_number = p_to_table,
            updated_at   = timezone('utc',now())
        where id = v_order.id;
      else
        -- Update source with remaining items
        update public.table_orders
        set items      = v_new_items,
            updated_at = timezone('utc',now())
        where id = v_order.id;
        -- Insert moved items as new order at destination
        insert into public.table_orders (seller_id, table_number, items, status, created_at)
        values (p_seller_id, p_to_table, coalesce(v_moved_items,'[]'::jsonb), 'new', timezone('utc',now()));
      end if;
    end if;
  end loop;

  -- Log the transfer
  insert into public.table_transfers_log (
    seller_id, from_table, to_table, transfer_type,
